import type { Post } from './posts';

// Original editorial scenarios. All HTML below is static, code-authored content.
type Source = readonly [string, string];
const nmap = (page: string): Source => ['Nmap resmi başvuru kılavuzu', `https://nmap.org/book/${page}.html`];
const rfc = (number: number): Source => [`RFC ${number}`, `https://www.rfc-editor.org/rfc/rfc${number}`];
const onvif = (profile: string): Source => [`ONVIF Profile ${profile.toUpperCase()}`, `https://www.onvif.org/profiles/profile-${profile}/`];
const axis = (page: string): Source => ['Axis teknik dokümantasyonu', `https://whitepapers.axis.com/en-us/${page}`];
const hardening: Source = ['AXIS OS Hardening Guide', 'https://help.axis.com/en-us/axis-os-hardening-guide'];
const discovery = 'IP Scanner ve Network Discovery';
const cameras = 'CCTV ve IP Kamera Sistemleri';
function article(slug: string, title: string, category: string, excerpt: string, body: string, sources: Source[], related: string): Post {
  return { slug, date: '2026-10-11', category, title: { tr: title }, excerpt: { tr: excerpt }, body: { tr: `${body}<h2>Kaynaklar ve güncellik</h2><p>Teknik kaynaklar 11 Ekim 2026 tarihinde kontrol edildi. Senaryolar açıklama amacıyla hazırlanmıştır; ölçülmüş ürün performansı değildir. ${sources.map(([label, url]) => `<a href="${url}">${label}</a>`).join(' · ')}. İlgili okuma: <a href="/tr/blog/${related}">konunun temel rehberi</a>.</p>` } };
}

export const infinityDiscovery: Post[] = [
article('kesif-kapsami-sozlesmesi', 'Ağ keşfinden önce kapsam belgesi nasıl hazırlanır?', discovery,
'Taranacak adresleri, kaynak noktalarını ve hariç tutulacak sistemleri tek bir uygulanabilir keşif planına dönüştürün.',
`<p>Bir ağ keşfinin başarısı bulunan cihaz sayısından önce doğru alanın incelenmesine bağlıdır. Şube yöneticisinin “bütün ağı tarayın” talebi, VPN üzerinden erişilen başka şirketlerin ağlarını kapsamaz. Çalışmaya başlamadan hangi adreslerin hangi kuruluşa ait olduğunu, hangi saatlerde inceleme yapılabileceğini ve hangi cihazların hassas olduğunu belirleyin. Bu belge, sorun çıktığında kimin aranacağını da göstermelidir.</p>
<h2>Adres listesini iş kapsamına bağlayın</h2><p>Her hedef bloğuna konum, VLAN, sorumlu kişi ve amaç ekleyin. “Yazıcı envanteri” ile “bütün servislerin doğrulanması” aynı sorguları gerektirmez. DHCP sunucusundan alınan ağ tanımlarını mevcut yönlendirme belgeleriyle karşılaştırın. Önce hedef listesini bağlantı kurmadan inceleyin; Nmap list scan seçeneğinin varsayılan DNS sorguları oluşturabileceğini unutmayın. DNS trafiği de kapsamın bir parçasıdır.</p>
<h2>Hariç tutulan cihazların gerekçesini yazın</h2><p>Eski bir üretim kontrol cihazı, dış kuruluşun yönettiği güvenlik sistemi veya yalnızca bakım penceresinde erişilebilen sunucu için ayrı satır açın. İstisnayı yalnızca kişinin hatırlamasına bırakmayın. Adres değişebileceği için cihaz adı ve envanter kimliğini de saklayın. Hariç tutma dosyasını hedef dosyasıyla aynı değişiklik kaydında yönetin; bir sonraki çalıştırmada unutulan istisna planı geçersiz kılar.</p>
<h2>Örnek kabul maddeleri</h2><p>Üç katlı bir ofiste önce tek kattaki bilinen on cihazı kontrol edin. Tarayıcının doğru arayüzü kullandığını, sonuçların cihaz etiketleriyle eşleştiğini ve ağ izleme ekranında beklenmeyen yük oluşmadığını doğrulayın. Ardından diğer katları aynı yöntemle inceleyin. Bu örnek bir sıra önerisidir; on cihazın her ortam için güvenli sınır olduğu iddia edilmez. Üretim sorumlusu daha dar kapsam belirleyebilir.</p>
<h2>Çalıştırma kaydı ve durdurma ölçütü</h2><p>Başlangıç saati, komut seçenekleri, kaynak IP, kullanılan sürüm ve hedef dosyasının kopyası rapora girmelidir. Belirlenen uygulamada kesinti, beklenmedik cihaz yeniden başlaması veya izleme alarmı görülürse keşfi durdurun ve değişiklik sorumlusuyla değerlendirin. Başarılı bitiş, bütün adreslerin cevap vermesi değildir; kapsamın tamamının incelenmesi, yanıt alınamayan alanların açıklanması ve mevcut kanıtların teslim edilmesidir.</p>
<p>Son raporda erişilemeyen bir alt ağı silmeyin. “İncelenmedi”, “incelendi fakat yanıt alınmadı” ve “cihaz doğrulandı” ayrı durumlar olsun. Böylece bir sonraki ekip eksikliği cihaz yokluğu sanmaz. Kapsam belgesi, tarama çıktısı ve istisna listesi birlikte saklandığında değişen bir envanterin neden değiştiği yeniden kurulabilir.</p>`, [nmap('man-target-specification'), nmap('man-host-discovery')], 'cidr-alt-ag-hesaplama'),
article('envanter-kanit-guveni', 'Cihaz envanterinde kanıt ve güven seviyesi nasıl tutulur?', discovery,
'IP adresi, isim ve üretici tahminini aynı kesinlikte değerlendirmeden izlenebilir bir envanter oluşturun.',
`<p>Bir tarayıcı aynı satırda IP adresi, ana makine adı ve üretici gösterdiğinde bu alanların hepsi doğrudan cihazdan alınmış gibi görünebilir. Oysa biri anlık yanıttan, diğeri DNS kaydından, üçüncüsü adres öneki eşleşmesinden gelebilir. Envanterin amacı güzel bir tablo üretmek değil, hangi bilginin hangi koşullarda doğru kabul edildiğini korumaktır.</p>
<h2>Değer ile gözlemi ayırın</h2><p>“Yazıcı” değeri için kaynağı ayrıca kaydedin: yönetici onayı, yönetim arayüzü, hizmet bildirimi veya tahmin. Son görülme zamanı ile son doğrulama zamanı farklı olabilir. Cihaz bugün cevap vermiş olsa bile geçen ay girilen konum bilgisi yeniden doğrulanmış sayılmaz. Her alan için tarih tutmak, envanterin tamamına tek bir güncellik damgası vurmanın yarattığı belirsizliği azaltır.</p>
<h2>Basit bir üç seviyeli yaklaşım</h2><p>Doğrulanmış alan, yetkili kayıt veya cihazın yönetim bilgisiyle eşleşmiştir. Gözlenmiş alan, belirtilen kaynaktan alınmıştır fakat bağımsız doğrulaması yoktur. Tahmin edilen alan, dolaylı işaretten çıkarılmıştır. Bu etiketler matematiksel olasılık değildir; operasyon ekibinin karar kurallarıdır. Güven seviyesi düşük kayıtları otomatik silmek yerine doğrulama kuyruğuna alın. Aksi halde belirsiz cihazlar rapordan kaybolur.</p>
<h2>Bir yazıcı örneği</h2><p>192.168.40.18 adresi cevap veriyor, ters DNS adı “depo-printer” ve bir web servisi bulunuyor olsun. Bunlar fiziksel cihazın gerçekten depoda olduğunu kanıtlamaz. Bakım kaydı seri numarasıyla eşleştirilince konum doğrulanır. Adres daha sonra başka cihazda kullanılırsa eski konum yeni cihaza taşınmamalıdır. Kimlik eşleştirmesini yalnızca IP üzerinden yapan sistem burada yanlış sonuç verir.</p>
<h2>İhtilafları görünür bırakın</h2><p>İki kaynak çelişiyorsa son gelen verinin önceki kaydı sessizce ezmesine izin vermeyin. “DNS adı ile varlık kaydı farklı” şeklinde bir inceleme nedeni üretin. Son kullanıcı adı, işletim sistemi ve cihaz tipi gibi alanların hangi ekip tarafından düzeltilebileceğini tanımlayın. Değişiklik geçmişi sayesinde yanlış bir otomatik birleştirme geri alınabilir; yalnızca son tabloyu tutmak bu imkânı ortadan kaldırır.</p>
<p>Uygulamada önce küçük bir cihaz grubunu elle doğrulayın. Hangi alanların güvenilir çıktığını, hangilerinin sıkça değiştiğini görün. Bundan sonra otomasyon kurallarını genişletin. Nmap XML çıktısında hizmet tanımlamasının yöntemi ve güven bilgisi bulunabilmesi bu ayrımı destekler; aynı yaklaşımı diğer veri kaynaklarına taşımak editoryal bir envanter tasarım önerisidir.</p>`, [nmap('output-formats-xml-output'), rfc(2131)], 'ters-dns-cihaz-adi'),
article('kesif-kaynak-noktasi', 'Aynı ağ iki bilgisayardan neden farklı görünür?', discovery,
'Kaynak arayüzü, VLAN ve güvenlik politikalarının keşif sonuçlarını nasıl değiştirdiğini kontrollü karşılaştırmayla inceleyin.',
`<p>İki teknisyen aynı hedef listesini tarayıp farklı sayıda cihaz bulduğunda araçlardan birinin bozuk olduğu düşünülür. Önce iki bilgisayarın aynı ağ görünümüne sahip olup olmadığını kontrol etmek daha yararlıdır. Kablolu bakım bilgisayarı, misafir Wi-Fi bağlantısı ve VPN istemcisi aynı hedefe farklı yollardan ulaşabilir. Bir listenin daha uzun olması onu kendiliğinden daha doğru yapmaz.</p>
<h2>Karşılaştırılabilir koşullar oluşturun</h2><p>İki tarafta hedef listesini, tarama yöntemini, araç sürümünü ve çalışma saatini eşitleyin. Kaynak IP adresini, ağ maskesini, varsayılan rotayı ve aktif VPN bağlantılarını kaydedin. Bir bilgisayarın yerel ağda yaptığı adres çözümlemesi, diğerinin yönlendirilmiş ağdaki kontrolüyle aynı işlem değildir. Yerel MAC bilgisi görülebilmesi de topolojinin etkisidir; uzak uç için aynı ayrıntıyı beklemeyin.</p>
<h2>Fark tablosu hazırlayın</h2><p>Her hedefi “iki noktadan da görüldü”, “yalnızca A”, “yalnızca B” ve “ikisinden de yanıt yok” olarak gruplayın. Sadece toplam sayıları karşılaştırmak sorunu gizler. Ardından her gruptan bir temsilci seçin. Bilinen servis erişimini kontrol edin ve ilgili güvenlik duvarı kayıtlarıyla zamanını eşleştirin. Erişim izni olmayan noktadan cevap alınamaması, beklenen politika davranışı olabilir.</p>
<h2>Örnek: yönetim ağı ile çalışan ağı</h2><p>Bir anahtarın HTTPS yönetimi bakım VLAN'ından açılıyor, çalışan VLAN'ından zaman aşımına uğruyor olsun. Yönetim ekibi bu ayrımı özellikle tasarlamış olabilir. İkinci taramayı “cihaz kapalı” diye işaretlemek yanlıştır. Rapor satırına kaynak bölgeyi ve hizmeti eklediğinizde ifade kesinleşir: çalışan ağından yönetim servisine erişim doğrulanamadı. Cihazın genel çalışma durumu hakkında daha geniş iddia kurmayın.</p>
<h2>Doğru sonuç modelini seçin</h2><p>Envanterde cihazı tek varlık olarak tutun; görünürlük durumunu kaynak bölgeye bağlı gözlem olarak saklayın. Böylece bir cihaz hem bakım ağında erişilebilir hem başka bölgede erişilemez olabilir. Bu veri modeli sonradan segmentasyon kontrolünde de işe yarar. Politika değişikliği sonrası yalnızca beklenen yolların açıldığını eski gözlemlerle karşılaştırabilirsiniz.</p>
<p>Tarama sonuçlarını eşitlemek için güvenlik duvarını geçici olarak kapatmayın. Önce farkın beklenen güvenlik sınırını yansıtıp yansıtmadığını inceleyin. Çözüm kimi zaman tek merkezi tarayıcı yerine her bölgeye uygun yetkili toplama noktası kurmaktır. Bu karar erişim yetkileri, işletim maliyeti ve cihaz hassasiyetiyle birlikte verilmelidir.</p>`, [nmap('man-port-scanning-basics'), rfc(826)], 'varsayilan-ag-gecidi'),
article('kesif-negatif-sonuc', 'Tarama sonucundaki “bulunamadı” nasıl raporlanmalı?', discovery,
'Yanıt alınmaması ile cihazın bulunmamasını ayıran, operasyon ekiplerine açık görevler bırakan rapor modeli.',
`<p>Bir IP adresinin taramada görünmemesi cihazın kaldırıldığı anlamına gelmez. Uyku durumu, yanlış hedef listesi, politika değişikliği veya kısa gözlem süresi aynı görüntüyü oluşturabilir. Buna rağmen birçok envanter süreci görünmeyen cihazı otomatik siler. Sağlam bir süreç, yokluk iddiasının ne kadar güçlü olduğunu değerlendirir ve negatif sonucu kendi bağlamıyla saklar.</p>
<h2>Önce keşfin tamamlandığını doğrulayın</h2><p>Çalıştırma yarıda kesildiyse, hedef atlandıysa veya araç hata verdiyse “yanıt yok” bile demek fazla kesin olabilir. Tamamlanan adres aralıklarını ve tamamlanamayan işleri ayırın. Bir tarama dosyasının oluşması bütün hedeflerin işlendiğini göstermez. Başlangıç ve bitiş bilgisi, hata kayıtları ve hedef sayısı birlikte kontrol edilmelidir. Eksik çalıştırmayı tam taramayla karşılaştırmak sahte kayıp alarmı üretir.</p>
<h2>Durumlara son görülme zamanı ekleyin</h2><p>“Bu çalıştırmada gözlenmedi” alanına önceki başarılı gözlemi iliştirin. Bir dizüstünün dün görüldüğü, bir anahtarın ise altı ay önce kaydedildiği durumlar aynı öncelikte değildir. Cihaz rolüne göre inceleme süresi belirleyin. Sürekli çalışan altyapı için kısa, seyrek bağlanan saha bilgisayarı için daha uzun doğrulama döngüsü gerekebilir. Süreler kurumun çalışma düzeninden türetilmelidir.</p>
<h2>Örnek inceleme sırası</h2><p>Hafta sonu görünmeyen bir toplantı odası bilgisayarında önce kullanım takvimini kontrol edin. Pazartesi kullanıcı oturum açtığında yeniden gözlem yapın. Ağ geçidi gibi sürekli çalışması beklenen bir cihazda ise rota ve izleme kayıtlarını hemen karşılaştırın. İki durum için aynı “üç taramada yoksa sil” kuralı uygun değildir. Tekrarlanan başarısızlık ancak koşullar anlamlıysa kanıtı güçlendirir.</p>
<h2>Silme yerine yaşam döngüsü</h2><p>Kayıtları etkin, inceleme bekliyor, hizmet dışı ve arşivlenmiş gibi aşamalarda yönetin. Hizmet dışı kararı teknik gözlemle birlikte varlık sorumlusunun teyidini gerektirir. Arşiv kaydı eski adresin yeniden kullanımını açıklayabilir. Canlı listeden kaldırılan kayıt geçmiş raporlarda korunmalı, yeni cihazla aynı kimlik altında birleştirilmemelidir. Böylece bir denetimde geçmiş durum yeniden anlaşılabilir.</p>
<p>Negatif sonuç raporunun sonunda açık bir görev bulunmalıdır: kapsamı düzeltmek, farklı saat diliminde gözlemek, ilgili politika kaydını incelemek veya fiziksel varlığı doğrulamak. Sadece kırmızı bir “offline” rozeti sorunun sahibini ve sonraki adımı söylemez. İyi rapor belirsizliği gizlemeden ekiplerin hangi kontrolü yapacağını netleştirir.</p>`, [nmap('man-host-discovery'), nmap('man-output')], 'ping-yaniti-yok'),
article('envanter-degisim-karsilastirma', 'İki keşif çıktısı arasındaki gerçek değişiklik nasıl bulunur?', discovery,
'Yeni cihaz, değişen adres ve farklı tarama koşullarını birbirine karıştırmadan envanter farklarını sınıflandırın.',
`<p>İki CSV dosyasını satır satır karşılaştırmak hızlıdır; fakat ağdaki değişimi doğru anlatmayabilir. Satır sırası, DNS adının yazımı veya bir cihazın yeni DHCP adresi fark listesini büyütür. Amacınız dosyaların farklı olduğunu göstermek değil, hangi fiziksel varlığın ya da hizmetin değiştiğini belirlemektir. Bunun için önce karşılaştırmanın anahtarlarını tasarlayın.</p>
<h2>Kimliği adresten ayırın</h2><p>Aynı IP adresini kullanan iki gözlemin aynı cihaz olduğunu varsaymayın. Seri numarası veya yönetilen varlık kimliği gibi doğrulanmış alanlar varsa öncelik verin. MAC adresi yardımcıdır fakat bütün ağlarda görünmez; sanal ve özel adres kullanımlarında ayrıca değerlendirilir. Hiçbir güçlü kimlik yoksa kayıtları zorla birleştirmek yerine “olası eşleşme” olarak incelemeye bırakın.</p>
<h2>Karşılaştırma sözleşmesi hazırlayın</h2><p>Hangi alanların büyük küçük harften etkilenmediğini, boş değerlerin nasıl yorumlanacağını ve zaman damgalarının hangi bölgeyi kullandığını belirleyin. Önceki çalıştırmada sorgulanmayan hizmeti bugün bulunan “yeni açık port” olarak sunmayın. Yöntem veya kapsam değiştiyse rapor başında belirtin. Birim, biçim ve kaynak eşitlenmeden yapılan fark analizi yöneticiyi gereksiz müdahaleye yönlendirebilir.</p>
<h2>Örnek bir sınıflandırma</h2><p>Bir yazıcı .40 adresinden .72 adresine geçmiş ve seri numarası aynı kalmışsa “adres değişikliği” kaydı üretin. .40 üzerinde farklı seri numarası görülüyorsa “adres yeniden kullanımı” ekleyin. Önceki web servisi bu kez gözlenmemişse bunu cihaz kaybından ayrı değerlendirin. Hizmetin yapılandırması değişmiş, erişim politikası daraltılmış veya sorgu başarısız olmuş olabilir. Sonucu tek bir değişti etiketiyle daraltmayın.</p>
<h2>İnceleme kuyruğunu önceliklendirin</h2><p>Yeni yönetim servisi, beklenmeyen ağ bölgesindeki cihaz ve çelişen kimlik gibi olaylar önce incelenebilir. Normal DHCP hareketliliği daha düşük öncelikte tutulabilir. Kuralların neden alarm ürettiğini kayıt üzerinde gösterin. Ekip bir farkı onayladığında bu kararı ve gerekçesini saklayın; aksi halde aynı durum her çalıştırmada yeniden keşfedilmiş gibi görünür.</p>
<p>Ham çıktıları değişmez kopya olarak koruyup normalleştirilmiş karşılaştırmayı ayrı üretmek yararlıdır. Bir dönüştürme hatası fark edildiğinde kaynak veriye dönülebilir. XML gibi yapısal çıktı kullanılıyorsa şema değişikliklerine karşı ayrıştırıcıyı kontrol edin. Yeni alanın gelmesi sessizce bütün kayıtların yeni cihaz kabul edilmesine yol açmamalıdır. Önce küçük ve kimliği bilinen bir örnekle sonuçları doğrulayın.</p>`, [nmap('man-output'), rfc(2131)], 'dhcp-kira-suresi'),
article('kesif-dhcp-birlestirme', 'DHCP kayıtları keşif envanteriyle nasıl birleştirilir?', discovery,
'Adres kiralarını canlı cihaz kanıtı gibi kullanmadan DHCP ve tarama verilerinden daha sağlam bir envanter üretin.',
`<p>DHCP sunucusu adres dağıtımının kaydını tutar; ağ tarayıcısı ise belirli anda elde ettiği yanıtları gösterir. İki listeyi birleştirmek kapsama alanını genişletir fakat bunlar aynı gerçeği ölçmez. Kira süresi henüz dolmamış bir bilgisayar kapalı olabilir. Statik adres kullanan bir cihaz da DHCP listesinde hiç bulunmayabilir. Bu farkları veri modeline taşımadan birleştirme yapmayın.</p><h2>Kaynak alanlarını koruyun</h2><p>Kira başlangıcı, bitişi, istemci tanımlayıcısı, bildirilen ad ve adresi ayrı alanlar olarak alın. Tarama zamanını kira tarihinin yerine yazmayın. Cihazın verdiği adı doğrulanmış varlık adı kabul etmek de hatalıdır. DHCP kaydı, bu istemcinin hangi adresi kullanmak üzere yapılandırıldığını anlamaya yardımcı olur; fiziksel konumu veya en son kullanıcıyı tek başına söylemez.</p><h2>Birleştirme penceresini belirleyin</h2><p>Sabah alınan DHCP listesini akşamki taramayla eşleştirirken adres değişimi ihtimalini düşünün. Özellikle kısa kiralı misafir ağlarında yalnızca IP eşleştirmesi risklidir. Mümkünse iki veriyi yakın zamanlarda toplayın ve toplama zamanını saklayın. Eski veriyi silmeden yeni gözlem oluşturun. Geçmiş gözlemler adresin kimden kime geçtiğini araştırırken güncel tablodan daha değerli olabilir.</p><h2>Örnek: iki farklı sonuç</h2><p>.53 adresi DHCP listesinde var fakat taramada görülmüyor; kaydı “DHCP'de kayıtlı, canlı yanıt doğrulanmadı” şeklinde tutun. .80 taramada görünüyor fakat kira listesinde yok; statik yapılandırma veya başka adres yönetim kaynağı araştırılsın. İkinci durumun otomatik olarak kaçak cihaz olduğu sonucuna varmayın. Yönetilen yazıcılar ve altyapı arayüzleri özellikle sabit adres kullanıyor olabilir.</p><h2>Rezervasyon ile mevcut kira ayrımı</h2><p>Bir rezervasyon yapılandırması cihazın bugün ağa bağlandığını göstermez. Eski cihaz çıkarıldıktan sonra rezervasyon unutulmuş olabilir. Rezervasyon kaydına hizmet sahibi ve kontrol tarihi ekleyin. Adres boşaltma kararını yalnızca tarayıcının cevap alamamasına dayandırmayın; yapılandırma kayıtları ve işletim sorumlusu birlikte değerlendirmelidir. Yanlış serbest bırakma daha sonra adres çakışması yaratabilir.</p><p>İlk uygulamada küçük bir alt ağı seçip üç liste hazırlayın: ortak kayıtlar, yalnızca DHCP'de bulunanlar ve yalnızca taramada bulunanlar. Her grubun birkaç örneğini elle doğrulayarak eşleştirme kuralını sınayın. Uyum oranı düşükse daha fazla tarama yapmak yerine zaman eşleştirmesini ve kimlik alanlarını gözden geçirin. Envanter kalitesini kayıt sayısı kadar açıklanabilen kayıt oranıyla da değerlendirin.</p>`, [rfc(2131), nmap('man-host-discovery')], 'dhcp-kira-suresi'),
article('envanter-coklu-arayuz', 'Çok arayüzlü cihazları envanterde tek varlık olarak tutmak', discovery,
'Ethernet, Wi-Fi, VPN ve sanal arayüzlerin aynı bilgisayarı çoğaltmasını önleyen kimlik modeli.',
`<p>Bir dizüstü bilgisayar kablolu bağlantı, kablosuz bağlantı ve VPN üzerinden üç farklı adresle görülebilir. Basit bir IP listesi bunu üç cihaz olarak sayar. Tersi de mümkündür: zaman içinde üç bilgisayar aynı adresi kullanır ve tek cihaz zannedilir. Doğru envanter, cihazı, arayüzü ve zaman içinde kullanılan adresleri ayrı kavramlar olarak saklar.</p><h2>Üç katmanlı kayıt yapısı</h2><p>Varlık kaydı fiziksel veya yönetilen mantıksal cihazı temsil eder. Arayüz kaydı bu varlığa bağlı ağ bağlantısını anlatır. Adres gözlemi ise belirli arayüzün belirli zaman ve ağ kapsamında kullandığı değerdir. Bu ayrım fazla karmaşık görünse de çift ağ kartlı sunucular ve IPv6 kullanan istemcilerde yanlış cihaz sayısını önlemenin temelidir.</p><h2>Birleştirme için yeterli kanıt arayın</h2><p>İki kaydın adının aynı olması güçlü bir başlangıç olabilir fakat kesin eşleşme değildir. Klonlanmış sistemler aynı adı taşıyabilir. Yetkili cihaz yönetimi sistemi veya seri numarası gibi kaynaklarla bağlantıyı doğrulayın. Aynı üretici ve benzer adresler yeterli değildir. Şüpheli kayıtları birleştirmeden ilişkilendirmek, yanlış birleştirmenin geçmişi bozmasından daha kolay geri alınır.</p><h2>Örnek: bakım dizüstü</h2><p>Teknisyenin bilgisayarı ofiste Ethernet, sahada Wi-Fi kullanıyor olsun. İki arayüzü aynı varlığa bağladığınızda son görüldüğü ağları ayrı görebilirsiniz. VPN arayüzünü de üçüncü bağlantı olarak tutun; VPN adresi fiziksel konum göstergesi değildir. Raporun “cihaz sayısı” varlıkları, “aktif adres sayısı” ise adres gözlemlerini saymalıdır. Bu iki ölçütün eşit olması beklenmez.</p><h2>IPv6 kayıtlarında kapsam</h2><p>Link-local adresleri saklarken ağ veya arayüz kapsamını kaybetmeyin. Aynı metin farklı bağlantılarda anlam kazanabilir. Geçici adresleri sürekli yeni fiziksel cihaz olarak değerlendirmeyin. Komşu keşfi, gözlemin hangi bağlantıda yapıldığını anlamaya yardımcı olur; tek başına kuruluş çapında değişmez kimlik üretmez. Adresin süresi ve kaynak noktası bu nedenle önemlidir.</p><p>Veri modelini değiştirirken önce mevcut kayıtların yedeğini alın. Otomatik birleştirmeleri küçük bir grupta çalıştırıp cihaz sahibiyle kontrol edin. Eski kimlikleri yeni varlığa eşleyen bir geçiş tablosu saklayın. Yanlış eşleşme bulunduğunda iki kaydı tekrar ayırabilmek gerekir. Birleşmiş kayıtlardaki son görülme tarihinin hangi arayüzden geldiği de raporda anlaşılır olmalıdır.</p>`, [rfc(4861), rfc(2131)], 'ipv6-adres-turleri'),
article('kesif-dns-bagimliligi', 'İsim çözümleme yavaşsa keşif süresini nasıl ayırırsınız?', discovery,
'Ağ yanıtı bekleme süresi ile ters DNS bekleme süresini ayrı ölçerek taramanın neden uzadığını bulun.',
`<p>Bir keşif ekranı uzun süre aynı adreste kalınca hedef cihazın yavaş olduğu düşünülebilir. Oysa araç cihaz yanıtını almış, ardından isim çözümlemesini bekliyor olabilir. Sonuç listesindeki ad sütunu yararlı olsa da temel erişim gözlemiyle aynı iş değildir. Toplam süreyi yorumlamak için keşif ve isim zenginleştirme aşamalarını ayrı değerlendirin.</p><h2>Kontrollü karşılaştırma kurun</h2><p>Aynı küçük hedef listesini aynı kaynak noktadan önce mevcut ayarlarla, sonra aracın belgelenmiş isim çözümlemeyi kapatma seçeneğiyle çalıştırın. Nmap için <code>-n</code> seçeneği DNS çözümlemesini kapatır. Bu örnek yöntemi başka uygulamaya aynı seçenekle taşımayın; her aracın ayarını kendi dokümanından doğrulayın. Tarama yöntemi ve hedef sayısı sabit kalmalıdır.</p><h2>Süre farkını doğru okuyun</h2><p>İkinci çalışma hızlı biterse DNS aşaması araştırılabilir; bu, bütün gecikmenin DNS kaynaklı olduğunu kesin kanıtlamaz. Ağ yükü ve önbellek etkileri de değişmiş olabilir. Tekrarlı küçük karşılaştırmalar ve çözümleyici kayıtları daha sağlam kanıt verir. İki sonuçtaki cihaz sayısı değişiyorsa yalnızca süreye odaklanmayın. Beklenmeyen farkı yöntem veya hata kayıtlarıyla açıklayın.</p><h2>Örnek işletim düzeni</h2><p>Gece envanterinde önce adres ve erişim gözlemlerini tamamlayıp isimleri ikinci aşamada ekleyebilirsiniz. Böylece ad sorguları başarısız olsa bile cihaz gözlemi kaybolmaz. Ad alanına boş metin yazmak yerine çözümleme durumunu tutun. “Kayıt yok”, “sunucu yanıt vermedi” ve “henüz sorgulanmadı” farklı işlemler gerektirir. Başarısız sorguların süresiz tekrar edilmesini de sınırlayın.</p><h2>İç adların hangi sunucuya gittiği</h2><p>Kurumsal özel alanlar genel DNS hizmetinde bulunmayabilir. Daha hızlı olduğu düşüncesiyle çözümleyiciyi değiştirmek iç adları bozabilir ve isimleri dış sisteme gönderebilir. Tarayıcının işletim sistemi ayarını mı, kendi sunucu listesini mi kullandığını belirleyin. Özellikle VPN bağlantısında bölünmüş DNS tasarımı isim çözümlemesinin hangi yoldan yapılacağını etkiler.</p><p>Son raporda cihaz keşif süresi, isim tamamlama süresi ve isimlenemeyen kayıt sayısını ayrı gösterin. Bir envanterin kullanılabilir olması bütün cihazların anlamlı ada sahip olmasını gerektirmez; kimlik alanları başka kaynaklardan doğrulanabilir. DNS optimizasyonu yaparken amaç saniye kazanmanın yanında hatanın hangi aşamada oluştuğunu görünür kılmaktır. İsimleri hız uğruna yanlış cihazlara eşleştirmeyin.</p>`, [nmap('man-host-discovery'), nmap('man-target-specification')], 'ters-dns-cihaz-adi'),
article('kesif-hizmet-adi-guveni', 'Açık porttan ürün adı çıkarmak neden hatalı olabilir?', discovery,
'Port numarası, servis yanıtı ve doğrulanmış yazılım sürümünü ayrı tutarak envanterde yanlış ürün eşleşmesini azaltın.',
`<p>443 numaralı portun açık olması cihazın belirli bir web sunucusunu kullandığını söylemez. Port numaraları yaygın hizmetlerle ilişkilidir fakat uygulamalar farklı portlarda çalışabilir. Keşif raporunda görülen servis adı bazen yalnızca bu eşleştirme tablosundan gelir. Ürün veya sürüm bilgisi gibi sunulduğunda bakım ve güvenlik kararları yanlış temele dayanır.</p><h2>Üç ayrı kanıt düzeyi</h2><p>İlk düzey bağlantının kabul edildiğidir. İkinci düzey uygulamanın protokole uygun yanıt verdiğidir. Üçüncü düzey belirli ürün veya sürüm bilgisinin doğrulanmasıdır. Bunları tek “servis bulundu” sütununda toplamayın. Nmap sürüm tespiti ayrı bir işlem olarak belgelenir; daha fazla sorgu üretmesi nedeniyle her keşif çalışmasına otomatik eklenmesi gerekmez.</p><h2>Banner verisini ihtiyatla değerlendirin</h2><p>Bir servis kendisini metinle tanıtabilir ancak bu metin eski, özelleştirilmiş veya aradaki vekil sunucuya ait olabilir. Envantere bildirilen değeri kaydedin; doğrulanmış kurulum bilgisiyle eşitlemeyin. Yama takibi için paket yönetimi veya üreticinin yönetim arayüzü gibi yetkili kaynaklar daha uygun olabilir. Sürüm metni tek başına güvenlik açığının varlığını veya yokluğunu kanıtlamaz.</p><h2>Örnek: aynı port, farklı katman</h2><p>Bir yazıcının HTTPS arayüzü ile ters vekilin HTTPS uç noktası aynı portta dinliyor olabilir. Tarama ikisinde bağlantı bulur. İlkinde cihaz yönetimi, ikincisinde farklı uygulamalara yönlendirme vardır. Bu iki kaydı “web sunucusu” başlığında birleştirmek iş sahiplerini karıştırır. Hizmet amacı, gözlenen protokol ve varlık tipi ayrı alanlar olmalıdır.</p><h2>Gereken ayrıntıyı amaçtan seçin</h2><p>Sadece cihaz erişimini izliyorsanız ürün parmak izi toplamak gereksiz olabilir. Yazılım geçişi planlıyorsanız doğrulanmış sürüm gerekir. Eski veya hassas cihazlarda aktif sürüm sorgularını bakım planıyla değerlendirin. Yeni bir yöntemi önce temsilci cihaz üzerinde deneyin ve uygulama günlüklerini kontrol edin. Daha ayrıntılı sonuç her durumda daha güvenli veya daha yararlı sonuç demek değildir.</p><p>Rapor etiketlerini açık yazın: “port tablosuna göre olası hizmet”, “protokol yanıtı gözlendi” ve “yönetim kaydıyla doğrulandı”. Böylece sonuç başka ekibe geçtiğinde belirsizlik kaybolmaz. Çelişen bilgiler için kaynakları yan yana saklayın. Doğru cihazı yanlış yazılım grubuna atamaktansa inceleme bekleyen bir kayıt bırakmak bakım sürecinin güvenilirliğini korur.</p>`, [nmap('man-version-detection'), nmap('output-formats-xml-output')], 'tcp-udp-port-farki'),
article('kesif-asamali-tarama', 'Büyük ağlarda keşfi aşamalara bölmek', discovery,
'Önce erişim, sonra ihtiyaç duyulan hizmet ayrıntısı: büyük hedef listelerini izlenebilir ve geri alınabilir işlere ayırın.',
`<p>Büyük bir adres listesinin her cihazında bütün özellikleri sorgulamak ilk bakışta kapsamlı görünür. Fakat tamamlanma süresi uzadıkça hataları ayırmak ve ara sonuçları kullanmak zorlaşır. Aşamalı keşif, önce temel görünürlüğü belirler; daha sonra yalnızca iş amacının gerektirdiği ayrıntıyı toplar. Böylece bir alt görev başarısız olduğunda bütün envanterin yeniden çalıştırılması gerekmez.</p><h2>Aşamaları farklı çıktılarla tanımlayın</h2><p>İlk aşamada hedef ve kapsam doğrulanır. İkincisinde erişim gözlemi alınır. Üçüncüsünde seçilen hizmetler veya yetkili yönetim bilgileri eklenir. Son aşamada kimlik eşleştirmesi ve insan incelemesi yapılır. Her aşamanın tamamlanma durumunu saklayın. Temel keşifte yanıt alınamayan hedeflerin sonraki aşamaya geçirilip geçirilmeyeceği açık kural olmalıdır; otomatik dışlama bazı cihazları gizleyebilir.</p><h2>Adres bloğuna göre değil işletime göre bölün</h2><p>Bir üretim hattı ile ofis istemcilerini aynı iş grubunda çalıştırmak gereksiz risk yaratabilir. Bölümleri cihaz hassasiyeti, ağ yolu ve bakım saatine göre düzenleyin. Hedef sayısı aynı olan iki grup farklı gecikme ve filtreleme davranışı gösterebilir. Sabit grup büyüklüğünü evrensel en iyi değer olarak sunmayın; küçük bir pilot çalışma ile uygun sınırı seçin.</p><h2>Örnek çalışma planı</h2><p>Beş şubeli işletmede her şubenin temel envanteri ayrı dosyada tamamlanabilir. Yalnızca yazıcı yönetimi gereken şubelerde ilgili hizmet ayrıntısı eklenir. VPN kesilen bir şubenin işi beklerken diğerleri raporlanabilir. Merkez raporunda hangi şubenin hangi aşamada olduğu görünür. Kısmi sonuçlar bütün kurum taraması bitmiş gibi sunulmaz; eksik kapsam açıkça işaretlenir.</p><h2>Tekrar çalıştırılabilirlik</h2><p>Hedef listesini ve parametreleri sürümleyin. Aynı iş tekrarlandığında eski sonuçları doğrudan ezmek yerine yeni çalıştırma kimliği üretin. Bir aşamadan diğerine geçirilen kayıtların neden seçildiğini saklayın. Başarısız sorgulara kontrollü tekrar hakkı verin fakat bitmeyen döngüler oluşturmayın. Operatörün işi durdurup daha sonra nereden devam edeceğini bilmesi gerekir.</p><p>Verimlilik yalnızca saniye cinsinden ölçülmez. Tamamlanan kapsam, açıklanan hatalar ve gereksiz sorgu sayısı da değerlendirilmelidir. Aşamalı planla sorgu yükünü azaltmak mümkündür; belirli hız kazanımı ancak kendi ağınızda ölçülür. Nmap zamanlama belgeleri seçeneklerin ödünleşimlerini açıklar. Bu bilgiyi doğrudan en agresif ayarı seçmek yerine iş kapsamını sadeleştirmek için kullanın.</p>`, [nmap('man-performance'), nmap('man-target-specification')], 'tarama-zaman-asimi'),
article('kesif-pasif-gozlem', 'Pasif gözlem cihaz envanterine ne ekler?', discovery,
'Yeni sorgu göndermeden görülen trafiğin güçlü ve zayıf yanlarını değerlendirin; sessiz cihazları yok saymayın.',
`<p>Pasif gözlem, cihazlara keşif sorgusu göndermek yerine mevcut ağ trafiğinden bilgi çıkarır. Bu yaklaşım bazı hassas ortamlarda yararlıdır fakat ağın eksiksiz fotoğrafını otomatik olarak vermez. Görülen trafik, seçilen gözlem noktasından geçen trafiktir. Bir anahtardaki sıradan bağlantı noktası bütün komşu cihazların paketlerini göstermez. Toplama mimarisini anlamadan sonuçları kuruluş geneline yaymayın.</p><h2>Gözlem penceresini tanımlayın</h2><p>On dakikalık dinleme sırasında sessiz kalan yazıcı ile bütün gün çalışan sunucu aynı görünürlükte olmaz. İş akışlarını kapsayan anlamlı bir pencere seçin. Haftalık görev çalıştıran bir sistem kısa gözlemde kaçabilir. Raporun başına başlangıç, bitiş, gözlem noktası ve hangi trafik sınıflarının görülebildiğini yazın. “Ağda yok” yerine “bu pencerede gözlenmedi” ifadesini kullanın.</p><h2>İçeriği değil gerekli metaveriyi toplayın</h2><p>Envanter için kaynak adres, zaman ve protokol gibi sınırlı bilgiler yeterli olabilir. Uygulama içeriklerinin gereksiz kaydı hem veri hacmini hem erişim riskini artırır. Toplama amacını ve saklama süresini belirleyin. Ham paket gerekiyorsa erişimi yetkili ekiple sınırlayın; raporlama için gerekli alanları ayrı çıkarın. Hassas kullanıcı trafiğini teknik merak amacıyla saklamayın.</p><h2>Örnek: seyrek çalışan cihaz</h2><p>Depo terminali yalnızca vardiya başında sunucuya bağlanıyor olsun. Öğleden sonraki kısa gözlemde görünmemesi normaldir. Vardiya saatini kapsayan kayıt veya yetkili DHCP bilgisiyle eşleştirme daha anlamlı olur. Buna karşılık görülen kaynak adresinin gün boyunca aynı fiziksel terminale ait olduğunu varsaymayın; adres kira değişimleriyle birlikte değerlendirin. Zaman boyutu olmadan pasif kayıt kolayca yanlış eşleşir.</p><h2>Aktif keşifle birlikte kullanım</h2><p>Pasif gözlem aday cihaz listesini geliştirebilir; yetkili aktif sorgu bu adayların güncel erişimini kontrol edebilir. İki yöntemin anlaşamadığı kayıtlar inceleme kuyruğuna alınmalıdır. Pasifte görülen fakat aktif sorguya yanıt vermeyen cihaz beklenen güvenlik politikası altında olabilir. Aktifte görülen fakat pasifte bulunmayan cihaz da henüz trafik üretmemiş olabilir. Çelişkiyi araç hatası olarak etiketlemeyin.</p><p>Uygulamaya geçmeden önce bilinen iki cihazı ve normal iş trafiğini örnek alın. Gözlem noktasında hangi paketlerin yakalanabildiğini doğrulayın. ARP ve mDNS gibi yerel protokoller bağlama dair ipuçları sağlar; fakat başka ağ bölgesindeki cihazları kendiliğinden kapsamaz. Kaliteli pasif envanter, toplam kayıt kadar görünmeyen alanları da açıkça tarif eder.</p>`, [rfc(826), rfc(6762)], 'arp-tablosu-okuma'),
article('kesif-hizmet-ornekleri', 'Bir DNS-SD kaydı kaç cihazı temsil eder?', discovery,
'Servis örneği, ana makine ve fiziksel cihazı ayırarak yazıcı ve medya hizmetlerinde mükerrer envanteri önleyin.',
`<p>Bir keşif aracında aynı yazıcı için birden fazla isim görmek cihazın çoğaldığı anlamına gelmeyebilir. Tek fiziksel ürün farklı baskı, tarama ve yönetim hizmetleri yayımlayabilir. DNS-SD hizmet örneklerini tanımlar; bunları doğrudan cihaz sayısı olarak kullanmak envanteri şişirir. Önce keşfedilen nesnenin cihaz mı yoksa hizmet duyurusu mu olduğunu belirleyin.</p><h2>Hizmet örneğini ayrı kayıt yapın</h2><p>Örnek adı, hizmet türü, hedef ana makine ve port ayrı alanlardır. Aynı hedefe işaret eden iki örneğin amacı farklı olabilir. Ayrıca bir hedefin birden fazla adresi bulunabilir. Bu nedenle örnek adını IP alanının yerine koymayın. DNS-SD kaydını uygulamanın sunduğu bağlantı bilgisi olarak saklayıp cihaz envanteriyle kontrollü ilişkilendirin.</p><h2>Duyuru ile çalışma testi farklıdır</h2><p>Bir hizmetin ilan edilmesi gerçek işlemin başarıyla tamamlandığını göstermez. Kullanıcı arayüzünde “keşfedildi” ile “işlev doğrulandı” ayrı olsun. Örneğin yazıcı hizmeti bulunmuş olsa bile sürücü, yetki veya kuyruk sorunu bulunabilir. İlk bağlantı testinde yalnızca gerekli ve yetkili işlemi yapın. Envanter çıkarmak için bütün yazıcılara deneme sayfası göndermek gereksiz olabilir.</p><h2>Örnek eşleştirme kararı</h2><p>“Kat2-Baski” ve “Kat2-Tarama” örnekleri aynı hedef adını ve adresini gösteriyorsa bunları tek cihazın iki hizmeti olarak aday eşleştirin. Yönetim arayüzündeki seri numarasıyla doğrulama yapıldığında ilişki güçlenir. Hedef daha sonra değişirse hizmet kaydını yeni gözlem olarak tutun. Eski cihaz ilişkisini otomatik taşımayın; bir hizmet başka sunucuya aktarılmış olabilir.</p><h2>Ağ sınırlarını hesaba katın</h2><p>mDNS ile bulunan hizmetler çoğunlukla yerel bağlantı kapsamıyla ilişkilidir. Kurumda özel yansıtıcı veya ağ geçidi varsa başka bölgelerden de duyuru gelebilir. Böyle bir yapı yokken hizmetin farklı VLAN'da görünmemesi beklenebilir. Hızlı çözüm olarak bütün multicast trafiğini açmak yerine işin gerçekten bölgeler arası keşif gerektirip gerektirmediğini değerlendirin. Güvenlik ve kullanıcı deneyimi aynı tasarım kararının parçalarıdır.</p><p>Rapor ekranında cihaz sayısını hizmet sayısından ayırın. Kullanıcı “12 cihaz, 31 hizmet” ifadesini gördüğünde keşfin ölçeğini daha doğru anlar. Hizmetler geçici olarak kaybolduğunda fiziksel varlığı silmeyin. Son duyuru, son bağlantı kontrolü ve son kimlik doğrulama tarihlerinin ayrı tutulması bakım sırasında yanlış müdahaleyi önler.</p>`, [rfc(6763), rfc(6762)], 'dns-sd-hizmet-kesfi'),
article('kesif-snmp-yetki-tasarimi', 'Envanter için SNMP hesabına ne kadar yetki verilmeli?', discovery,
'Cihaz yönetimini keşif işleminden ayıran, salt okunur ve denetlenebilir SNMP erişimi tasarlayın.',
`<p>Ağ envanteri için anahtarın modelini ve arayüzlerini öğrenmek, yapılandırmasını değiştirme yetkisi gerektirmez. Buna rağmen hızlı kurulum sırasında geniş yönetim yetkileri verilebilir. Keşif sisteminin hesabı ele geçirildiğinde etkisi de bu yetkilerle büyür. Envanter hesabını görev için gereken bilgiye erişen ayrı bir işletim kimliği olarak tasarlamak daha denetlenebilir bir yaklaşımdır.</p><h2>Kimlik, erişim ve veri kapsamı</h2><p>SNMPv3 güvenlik özellikleri kimlik doğrulama ve gizlilik seçenekleri sunar; tek başına doğru yetkilendirme politikasını oluşturmaz. Cihazın desteklediği güvenlik modu ve erişim görünümü ayrıca yapılandırılmalıdır. Kullanılan şifreleme ve doğrulama algoritmalarını üreticinin güncel dokümanından seçin. Eski bir örnek komutu bütün modellere kopyalamak yerine her cihaz ailesinin yeteneklerini doğrulayın.</p><h2>Toplanacak alanları önceden listeleyin</h2><p>Model, seri numarası, yazılım sürümü, arayüz adı ve durum gibi gerçekten gerekli verileri belirleyin. Bütün yönetim ağacını periyodik olarak çekmek gereksiz hacim yaratabilir. Hassas açıklama alanlarında personel isimleri veya konum bilgisi bulunabilir. Rapora hangi alanların aktarılacağını, kimlerin göreceğini ve ne kadar süre saklanacağını veri sahibiyle kararlaştırın.</p><h2>Örnek pilot uygulama</h2><p>Bir erişim anahtarında yalnızca envanter sorgularını çalıştırın. Yetki eksikse hangi alanın reddedildiğini kaydedin; bütün yönetim haklarını açmak yerine ilgili görünümü inceleyin. Salt okunur hesabın değişiklik yapamadığını cihazın erişim politikası üzerinden doğrulayın. Keşif sunucusunun adresini izinli kaynak olarak sınırlamak ek kontrol olabilir; bu, güçlü kimlik doğrulamanın yerine geçmez.</p><h2>Kimlik bilgilerinin yaşam döngüsü</h2><p>Parolaları betik dosyasında veya ortak raporda saklamayın. Kurumun sır yönetimi yöntemini kullanın. Hesap sahibini, kullanım amacını ve yenileme sürecini belgeleyin. Cihazlar değiştiğinde eski hesabın gereksiz yere açık kalmaması için hizmetten çıkarma adımı ekleyin. Başarısız doğrulama sayısındaki artış parola değişimi, yanlış yapılandırma veya başka bir olayı gösterebilir; zaman çizelgesiyle araştırın.</p><p>Keşif başarısını yalnızca dolu alan oranıyla ölçmeyin. Gereksiz ayrıcalık verilmemesi ve başarısız sorguların açıklanması da kabul ölçütüdür. Desteklenmeyen alanı boş bırakmak, yönetim hesabını genişletmekten daha doğru olabilir. SNMP verisinin cihazın bildirdiği bilgi olduğunu unutmayın; kritik kimlik eşleştirmelerinde varlık kaydı veya fiziksel etiketle örnek doğrulama yapın.</p>`, [rfc(3414), hardening], 'arp-tablosu-okuma'),
article('kesif-sanal-aglar', 'Sanal makineler ve konteynerler cihaz sayısını neden değiştirir?', discovery,
'Fiziksel varlık, sanal uç nokta ve geçici servis adreslerini ayrı envanter katmanlarında değerlendirin.',
`<p>Bir fiziksel sunucunun onlarca IP adresine hizmet vermesi modern altyapıda olağandır. Sanal makineler, konteyner ağları ve servis adresleri taramada ayrı uçlar gibi görünebilir. Bunların hepsini fiziksel cihaz olarak saymak kapasite planını bozar. Tam tersine bütün adresleri tek sunucuya indirgemek de hizmet sahipliğini kaybettirir. Envanterin hangi nesneyi saydığını baştan tanımlayın.</p><h2>Keşif ile platform kaydını eşleştirin</h2><p>Ağ üzerinden görülen adresleri yetkili sanallaştırma veya orkestrasyon envanteriyle karşılaştırın. IP tek başına kalıcı iş yükü kimliği değildir. Platformun sağladığı nesne kimliğini, oluşturulma zamanını ve sahibi olan uygulamayı saklayın. Ağ keşfi erişimi doğrularken platform kaydı nesnenin yaşam döngüsünü açıklar. İki kaynaktan biri diğerinin yerine geçmez.</p><h2>Geçici adresleri yeni donanım sanmayın</h2><p>Bir uygulama yeniden dağıtıldığında adres değişebilir; hizmet adı aynı kalabilir. Karşılaştırma sistemi her değişimde yeni fiziksel cihaz alarmı üretirse ekip gerçek olayları kaçırır. Geçici iş yükleri için farklı eskime kuralları kullanın. Ancak geçicilik gerekçesiyle bütün farkları bastırmayın; beklenmeyen ağ bölgesinde görülen iş yükü yine inceleme gerektirebilir.</p><h2>Örnek: yük dengeleyici önü ve arkası</h2><p>Kullanıcının bağlandığı sanal IP, arkasındaki üç uygulama örneğini temsil edebilir. Tarayıcı yalnızca ön uç servisini görürse üç sunucunun sağlıklı olduğunu söyleyemez. Arka uçların yönetim ağı ayrıca incelenmelidir. Raporda “hizmet adresi erişilebilir” ifadesini “bütün uygulama örnekleri çalışıyor” ifadesine dönüştürmeyin. Aradaki ilişki uygulama mimarisiyle doğrulanmalıdır.</p><h2>Raporlama düzeyleri</h2><p>Donanım raporu fiziksel varlıkları, işletim raporu sanal makineleri, uygulama raporu hizmet uçlarını sayabilir. Aynı temel gözlem farklı raporlarda farklı anlam taşır. Kullanıcıya hangi düzeyde olduğunu gösterin. Bir toplam rakamın başlığında yalnızca “cihazlar” yazması, sanal ve fiziksel nesnelerin karıştığı ortamlarda yetersizdir. Filtrelerin sayımı nasıl değiştirdiğini açıklayın.</p><p>İlk kontrol için bir sunucudaki bilinen iş yüklerini örnek alın. Platformdaki nesnelerle keşif kayıtlarının bire bir olması gerekmediğini gösteren bir eşleştirme tablosu hazırlayın. Görülmeyen kayıtların nedeni ağ politikası mı, geçici yaşam süresi mi, farklı adres kapsamı mı araştırın. Standartların adres çözümleme kuralları fiziksel donanım envanteri üretmez; bu ilişki kurumun yönetim verisiyle kurulmalıdır.</p>`, [rfc(826), nmap('man-port-scanning-basics')], 'ozel-ip-araliklari'),
article('kesif-cikti-dogrulama', 'Keşif XML ve CSV çıktılarında veri kaybı nasıl önlenir?', discovery,
'Dışa aktarma dosyasını yeniden kullanılabilir teknik kanıta dönüştüren biçim, kimlik ve tamamlanma kontrolleri.',
`<p>Bir keşif sonucunu tabloya aktarmak kolaydır; bütün anlamını korumak daha zordur. CSV dosyasında port numarası kalırken protokol, gözlem zamanı veya sonuç nedeni kaybolabilir. Sonraki ekip yalnızca sayıyı görür ve ilk taramanın neyi doğruladığını anlayamaz. Dışa aktarma biçimini raporlama sürecinin küçük bir ayrıntısı olarak görmeyin.</p><h2>Ham çıktı ile sunum dosyasını ayırın</h2><p>Aracın yapısal çıktısını değişmeden saklayın. Kullanıcının açacağı sade CSV dosyasını bundan üretin. Nmap XML biçimi ayrıntılı alanları taşıyabilir; buna rağmen ayrıştırıcınızın bu alanların hangilerini kullandığını belgeleyin. Yeni sürümde gelen bir alanın yok sayılması kabul edilebilir olabilir, fakat gerekli bir alanın sessizce boşalması hata olarak yakalanmalıdır.</p><h2>Kimlik ve zaman alanlarını koruyun</h2><p>Çalıştırma kimliği, kaynak ağ, hedef adres, protokol, port, durum ve zaman en azından değerlendirilmelidir. Bir IP adresini sayısal hücreye dönüştürmeyin. IPv6 kapsam bilgisi veya baştaki sıfırlar uygulamanızın normalleştirme kurallarıyla bilinçli ele alınmalıdır. Tarih alanını yerel görüntüleme biçimiyle değil, açık saat dilimi taşıyan biçimle saklamak farklı ekiplerin karşılaştırmasını kolaylaştırır.</p><h2>Örnek doğrulama seti</h2><p>Birden fazla adresi olan cihaz, virgül içeren ad, Türkçe karakter, boş servis alanı ve zaman aşımı kaydı içeren küçük bir örnek hazırlayın. Kaynak dosyada kaç gözlem varsa dönüşüm sonunda neden aynı veya farklı sayı çıktığını açıklayın. Bir cihazın birden fazla hizmet satırı üretmesi normal olabilir; bunu yanlışlıkla mükerrer kayıt temizliğiyle silmeyin.</p><h2>Tablo uygulamalarının davranışı</h2><p>CSV bir elektronik tablo programında açılırken otomatik tür dönüşümleri gerçekleşebilir. Dışarıdan alınan ad alanlarını formül olarak yorumlatmayan güvenli aktarım yöntemi kullanın. Veriyi ham kod gibi çalıştırmayın. Dosyanın gerçek içeriğiyle ekranda görünen biçim arasında fark olabileceğinden kritik karşılaştırmaları yalnızca görsel incelemeye bırakmayın. İçe aktarma seçeneklerini rapor prosedürüne ekleyin.</p><p>Tamamlanmamış XML veya yarıda kesilmiş CSV dosyalarını geçerli tam rapor olarak kabul etmeyin. Başarılı bitiş işareti, hata kaydı ve beklenen kapsam kontrolü birlikte değerlendirilmelidir. Dönüştürme betiğinin sürümünü dosyaya iliştirin. Aylar sonra aynı ham çıktı yeniden işlendiğinde farklı sonuç çıkarsa hangi kuralın değiştiği anlaşılır. İyi dışa aktarma, veriyi sadeleştirirken kanıtın kökenini kaybetmez.</p>`, [nmap('man-output'), nmap('output-formats-xml-output')], 'windows-ag-teshis'),
article('kesif-yeniden-deneme-butcesi', 'Keşif işlerinde tekrar deneme bütçesi nasıl belirlenir?', discovery,
'Geçici paket kaybına tolerans ile bitmeyen tarama arasında ölçülebilir bir denge kurun.',
`<p>Bir sorguya yanıt gelmediğinde tekrar denemek makuldür. Ancak her hedefi sınırsız tekrar etmek keşif işini bitmez hale getirir. Çok az tekrar da geçici kaybı cihaz yokluğu gibi gösterebilir. Doğru yaklaşım herkese uygulanan sihirli sayı bulmak değil, belirli işin gecikme ve kapsama gereksinimlerini açıkça tanımlamaktır.</p><h2>Üç farklı sınırı ayırın</h2><p>Tek sorgunun bekleme süresi, bir hedefe ayrılan toplam süre ve bütün işin son tarihi farklıdır. Birini kısaltmak diğerlerini otomatik çözmez. Araç bu sınırları destekliyorsa nasıl etkileştiklerini resmi belgelerden kontrol edin. Örneğin toplam hedef süresi dolduğunda ayrıntıların tamamlanmadan bırakılması mümkündür. Rapor bunu tam başarı olarak göstermemelidir.</p><h2>Önce küçük bir örnek gözleyin</h2><p>Yerel hızlı bağlantı ile uzak şube VPN'i aynı yanıt dağılımına sahip olmayabilir. Her bölgeden bilinen birkaç cihaz seçin ve normal çalışma saatlerinde gözlem yapın. Ortalama tek başına yetmez; aralıklı uzun gecikmeleri de not edin. Bu çalışma gerçek ölçüm gerektirir. Başka bir kurumun sürelerini kendi ağınız için başarı garantisi gibi kullanmayın.</p><h2>Örnek iki kuyruk modeli</h2><p>İlk geçişte temel sorgular tamamlanır. Yanıt alınamayan veya ayrıntısı eksik hedefler ikinci bir inceleme kuyruğuna alınır. İkinci kuyruk daha dar kapsamla, uygun zamanda çalıştırılır. Böylece bir avuç sorunlu hedef bütün raporun teslimini durdurmaz. Fakat raporun tamamlandığını söylerken ikinci kuyruğun durumunu açık tutun; ertelenmiş iş tamamlanmış iş değildir.</p><h2>Tekrarın neyi değiştirdiğini ölçün</h2><p>Ek denemelerde bulunan yeni cihaz sayısı ile harcanan süreyi karşılaştırın. Son denemeler hiçbir yeni kanıt getirmiyorsa başka nedenler araştırılmalıdır: rota, filtreleme, yanlış hedef veya kapalı servis. Daha çok paket göndermek her sorunu çözmez. Bir cihazın ilk denemede bulunup sonraki denemede kaybolması da sadece tarayıcı ayarıyla açıklanamaz; zaman çizelgesini inceleyin.</p><p>Operatöre kalan iş miktarı ve iptal edilen hedefler hakkında doğru bilgi verin. Hızlı görünen bir arayüz arka planda sürekli tekrar yapıyorsa kaynak tüketimi gizlenir. Çalıştırma sonunda zaman sınırına takılan kayıtları ayrı dışa aktarın. Nmap zamanlama seçeneklerinin belgelenmiş ödünleşimlerini incelemek başlangıç sağlar; son değerler kendi ağınızda ölçülerek seçilmelidir.</p>`, [nmap('man-performance'), nmap('man-output')], 'tarama-zaman-asimi'),
article('kesif-uyuyan-cihazlar', 'Uyuyan dizüstüler ve seyrek bağlanan cihazlar nasıl izlenir?', discovery,
'Anlık çevrimiçi listesini kalıcı varlık envanterinden ayırarak çalışan cihazları yanlışlıkla kayıp saymayın.',
`<p>Ofis envanterinde gece taraması bütün dizüstüleri kaçırabilir. Bu bir tarayıcı arızası değil, çalışma düzeninin sonucudur. Sunucular için uygun olan sürekli erişim beklentisini kullanıcı cihazlarına uygulamak yanlış alarm üretir. Envanterin “kuruma ait” sorusu ile “şu anda ağdan yanıt veriyor” sorusunu ayrı cevaplaması gerekir.</p><h2>Cihaz rolünü ilk sınıflandırma yapın</h2><p>Sürekli çalışan altyapı, vardiyalı terminal, kişisel çalışma cihazı ve geçici misafir uçlarını ayırın. Her grup için beklenen bağlantı düzenini tanımlayın. Bir dizüstünün hafta sonu görünmemesi olağan olabilirken ağ geçidinin aynı durumda olması inceleme gerektirir. Eşikler yalnızca teknik varsayımla değil, iş sahiplerinin onayıyla belirlenmelidir.</p><h2>Son görülme ile sahiplik aynı şey değildir</h2><p>Keşif kaydına son başarılı gözlem ekleyin; varlık sahibini ayrı yönetim kaynağından alın. Uzun süre görünmeyen cihaz personelin izinli olması, başka şubeye gitmesi veya arızalanması gibi farklı nedenlere sahip olabilir. Envanterden silmeden önce bu açıklamaları araştırın. Aynı zamanda belirsizliği süresiz uzatmayın; inceleme için sorumlu ve son tarih belirleyin.</p><h2>Örnek haftalık görünürlük</h2><p>Gezici satış ekibinin bilgisayarları yalnızca pazartesi sabahı kurumsal ağa bağlanıyorsa bu pencereyi kapsayan gözlem daha anlamlıdır. Salı gecesi taramasını tek doğruluk kaynağı yapmak cihazların tamamını kayıp gösterebilir. Pazartesi görülen cihazın bütün hafta sağlıklı çalıştığını da söyleyemezsiniz. Rapor gözlemin zamanla sınırlı olduğunu belirtmelidir.</p><h2>Uyandırma bir keşif varsayımı değildir</h2><p>Wake-on-LAN veya başka uzaktan uyandırma yöntemleri bazı ortamlarda kullanılabilir; destek, yapılandırma ve yetki gerektirir. Her cihazın tarama sırasında otomatik uyandırılabileceğini varsaymayın. Enerji politikası ve kullanıcı etkisi ayrıca değerlendirilmelidir. Envanter amacı için cihazı uyandırmak yerine mevcut yönetim kayıtlarını kullanmak daha uygun olabilir. Uygulamanın desteklemediği davranışı kullanıcıya vaat etmeyin.</p><p>Başlangıçta bir aylık gözlem örneği üzerinden yanlış alarm üreten grupları belirleyin. Gerçekten hizmetten çıkarılan birkaç cihazla hâlâ kullanılan fakat seyrek görünen cihazları karşılaştırın. Bu editoryal kontrol planı ölçüm sonucu değildir; kurumunuzun kendi verisiyle uygulanmalıdır. Çevrimiçi durumunu bir sağlık göstergesi olarak kullanırken tek başına sahiplik veya kullanım kararı haline getirmeyin.</p>`, [rfc(2131), nmap('man-host-discovery')], 'ping-yaniti-yok'),
article('kesif-cok-sube-adres-cakismasi', 'Aynı özel IP kullanan şubeler envanterde nasıl ayrılır?', discovery,
'Adresin yanına ağ bağlamı ekleyerek şubeler arası yanlış cihaz birleştirmesini önleyin.',
`<p>İki şubede de 192.168.1.10 adresinin bulunması tek başına çakışma değildir. Özel adresler bağımsız ağlarda tekrar kullanılabilir. Merkez envanter yalnızca IP adresini anahtar kabul ederse iki farklı cihazı birleştirir. VPN bağlantısı eklendiğinde yönlendirme sorunu da ortaya çıkabilir; fakat veri modelindeki kimlik hatası bundan bağımsızdır.</p><h2>Adresin bağlamını kayıt anahtarına katın</h2><p>Şube kimliği, ağ bölgesi veya adres alanı tanımı IP ile birlikte saklanmalıdır. Kullanıcıya görünen şube adı değişebilse de arka plandaki bağlam kimliği sabit kalmalıdır. “Merkez” gibi serbest metinler yazım farkları yüzünden mükerrer kayıt oluşturabilir. Bağlamları yönetilen bir listeden seçmek daha tutarlı sonuç verir. VLAN numarası tek başına kurum genelinde benzersiz olmayabilir.</p><h2>Toplama noktasını belirtin</h2><p>Her şubede yerel toplayıcı varsa hangi verinin nereden geldiğini kaydedin. Merkezden VPN üzerinden tarama yapılıyorsa hedef yolunun hangi şubeye ulaştığını doğrulayın. Adres aynı olduğu için yanlış şubeye giden sorgu doğru görünümlü fakat yanlış envanter üretir. Bilinen bir cihazın yönetim kimliğiyle örnek doğrulama bu hatayı erken ortaya çıkarabilir.</p><h2>Örnek birleşme hatası</h2><p>Ankara şubesindeki .10 yazıcı, İzmir şubesindeki .10 kayıt cihazı olsun. Merkez tablo son gelen veriyi aynı satıra yazarsa ürün tipi her çalıştırmada değişir. Bu gerçek cihaz değişimi değildir. İki ayrı ağ bağlamı açıp geçmiş gözlemleri doğru yerlere taşımak gerekir. Sadece son satırın adını düzeltmek veri modelindeki sorunu çözmez.</p><h2>Arama ve rapor ekranı</h2><p>IP ile arama birden fazla sonuç döndürebilmelidir. Her sonuçta şube, ağ ve son gözlem zamanı gösterin. Dışa aktarmada bağlam sütununu kaldırmayın; elektronik tabloda tekrar yanlış birleştirme yapılabilir. Global cihaz sayımı yapılırken doğrulanmış varlık kimliğini, adres kullanım raporunda ise bağlam ve adres çiftini kullanın. İki rapor farklı sorulara cevap verir.</p><p>Şubeleri ortak VPN'e bağlama planında adres örtüşmesi ayrıca değerlendirilmelidir. Bu yazı adres değişikliği veya NAT tasarımı için tek başına karar kılavuzu değildir; envanterin doğru tutulmasına odaklanır. Geçiş sırasında eski ve yeni bağlam ilişkilerini saklayın. Tarihsel kayıtta bir IP'nin hangi şubede anlam taşıdığı kaybolursa olay incelemeleri ve bakım kayıtları da belirsizleşir.</p>`, [rfc(1918), nmap('man-target-specification')], 'ozel-ip-araliklari'),
article('kesif-basari-metrikleri', 'Keşif kalitesi hangi ölçütlerle değerlendirilir?', discovery,
'Bulunan cihaz sayısının ötesine geçerek kapsam, açıklanabilirlik ve kimlik doğruluğunu ölçün.',
`<p>Bir tarayıcının çok cihaz bulması iyi görünebilir, fakat aynı cihazı iki kez sayıyorsa veya yanlış ağları kapsıyorsa sonuç güvenilir değildir. Keşif kalitesi tek sayıdan oluşmaz. Doğru kapsam, doğrulanabilir kimlik ve açıklanmış eksikler birlikte değerlendirilmelidir. Ürün seçimi veya işletim iyileştirmesi yaparken hangi soruya hangi ölçütün cevap verdiğini açık yazın.</p><h2>Kapsam tamamlanma oranı</h2><p>Planlanan hedeflerden hangileri gerçekten işlendi? Atlanan, zaman sınırına takılan ve yetki nedeniyle incelenmeyen gruplar ayrı gösterilmelidir. Payda yalnızca yanıt veren cihazlar olursa sonuç yanıltıcı olur. Hedef listesi değiştiğinde önceki dönemle doğrudan karşılaştırma yapmayın. Aynı yöntem ve kapsam altında toplanan sonuçlar daha anlamlı bir eğilim verir.</p><h2>Kimlik doğrulama oranı</h2><p>Gözlenen kayıtların ne kadarı yetkili varlık kaydıyla eşleşiyor? Burada amaç bütün alanları doldurmak değil, eşleşmenin kanıtını korumaktır. Tahmin edilen üretici bilgisini doğrulanmış model bilgisi olarak saymayın. Mükerrer kayıt oranını küçük elle doğrulanmış örneklerle inceleyin. Örnek seçimi yalnızca kolay bulunan cihazlardan oluşursa en zor alanlar görünmez kalır.</p><h2>Örnek kabul tablosu</h2><p>Bir pilotta bilinen yirmi varlığın hangi arayüzlerinin gözlendiğini, hangi kayıtların birleştirildiğini ve hangi eksiklerin açıklandığını listeleyin. Yirmi sayısı burada öğretici örnektir, istatistiksel yeterlilik iddiası değildir. Üretim ağı için örnek büyüklüğü cihaz çeşitliliğine bağlıdır. Kabul kararında görünmeyen bir cihazın gerekçesi bazen daha fazla bulunan cihaz sayısından değerlidir.</p><h2>Operasyonel maliyeti de ölçün</h2><p>Çalıştırma süresi, üretilen sorgu hacmi, insan inceleme süresi ve yanlış alarm sayısı birlikte ele alınmalıdır. En hızlı yöntem en çok manuel düzeltme gerektiriyorsa toplam süreç daha pahalı olabilir. Otomatik eşleştirme kuralları değiştiğinde önceki doğruluk örneklerini yeniden kontrol edin. Süre kazanımı için kimlik doğruluğunu sessizce düşürmeyin.</p><p>Raporların dilini de kabul ölçütü yapın. “Bulunamadı” ifadesi hangi koşulu anlatıyor, “aktif” hangi kanıta dayanıyor, “yeni” hangi önceki kayıtla karşılaştırılıyor? Bu tanımlar yoksa ekipler aynı tabloyu farklı yorumlar. Nmap durum ve çıktı belgeleri gözlemin araç bakışını taşıdığını gösterir; kurum raporu bu bağlamı kullanıcıya aktarmalıdır. Ölçütler iyi tanımlandığında iyileştirme gerçek bir sorunu hedefler.</p>`, [nmap('man-port-scanning-basics'), nmap('man-output')], 'tarama-zaman-asimi'),
article('kesif-devretme-paketi', 'Keşif raporu başka ekibe nasıl devredilir?', discovery,
'Ham çıktı, kapsam ve açık soruları bir araya getirerek envanteri yeniden üretilebilir bir teslimata dönüştürün.',
`<p>Bir dosya paylaşımına “son tarama” adlı CSV yüklemek işi devretmek için yeterli değildir. Dosyayı alan ekip hangi ağı, hangi zamanda ve hangi yöntemle incelediğinizi bilmiyorsa sonuçları doğru kullanamaz. İyi bir teslim paketi yalnızca bulunanları değil, yapılmayanları ve çözülemeyen soruları da açıklar. Böylece aynı inceleme gereksiz yere tekrarlanmaz.</p><h2>Pakette neler bulunmalı?</h2><p>Kapsam listesi, hariç tutulan hedefler, çalıştırma parametreleri, araç sürümü, kaynak noktası ve saat dilimi temel bilgiler arasındadır. Ham çıktıyı okunabilir özetle birlikte saklayın. Dosyaları anlamlı çalıştırma kimliğiyle adlandırın. Birden fazla tarama varsa hangi özetin hangi ham dosyadan üretildiğini ilişkilendirin. “Final2” gibi adlar teknik izlenebilirlik sağlamaz.</p><h2>Belirsizlikleri görev haline getirin</h2><p>Kimliği doğrulanmayan cihaz, erişilemeyen alt ağ ve çelişen ad kaydı için ayrı inceleme maddeleri oluşturun. Her maddede gözlem, olası açıklamalar ve önerilen sonraki kontrol yer alsın. Olası açıklamayı doğrulanmış neden gibi yazmayın. Görevin hangi ekibe ait olduğunu belirtmek önemlidir; DNS adı problemiyle fiziksel konum doğrulaması farklı sorumlulara gidebilir.</p><h2>Örnek devir notu</h2><p>“Depo ağındaki .24 adresi iki çalıştırmada cevap vermedi; hedef kapsamı doğrulandı, cihazın fiziksel durumu kontrol edilmedi” cümlesi açık ve sınırlıdır. “Depo cihazı arızalı” cümlesi ise kanıtı aşar. İlgili ham satıra ve gözlem saatlerine bağlantı verin. Sonraki ekip fiziksel kontrol yaptığında kendi bulgusunu aynı kayıt zincirine ekleyebilir.</p><h2>Gizli alanları ayıklayın</h2><p>Envanter kullanıcı adları, iç adlandırma ve yönetim adresleri içerebilir. Her alıcının bütün alanlara ihtiyacı olmayabilir. Kurum içi teknik paket ile dış paylaşım sürümünü ayırın. Erişim bilgileri veya parolalar raporda bulunmamalıdır. Maskeleme yapıldığında hangi alanların çıkarıldığını belirtin; aksi halde boş alanlar toplama hatası sanılabilir. Ham dosyaya erişim de iş gereksinimine bağlı olmalıdır.</p><p>Devir tamamlanırken küçük bir örneğin alıcı tarafından yeniden yorumlanmasını isteyin: cihaz sayısını, açık soruları ve kapsamı aynı şekilde anlayabiliyor mu? Bu kontrol yazılım testi değildir; dokümantasyonun kullanılabilirliğini sınar. İyi teslim, sonraki kişinin sizin sözlü açıklamanıza ihtiyaç duymadan karar verebildiği teslimdir. Keşif çıktısı ancak bağlamıyla birlikte kalıcı operasyon bilgisine dönüşür.</p>`, [nmap('man-output'), nmap('man-target-specification')], 'windows-ag-teshis'),
article('kamera-onvif-uygunluk-kontrolu', 'ONVIF uyumluluğunu satın alma öncesi nasıl doğrularsınız?', cameras,
'Logo veya pazarlama ifadesi yerine model, firmware ve gereken profil üzerinden kamera ile VMS eşleşmesini kontrol edin.',
`<p>Bir kameranın üzerinde ONVIF ifadesi bulunması bütün kayıt yazılımlarıyla bütün özelliklerinin çalışacağını garanti etmez. Gerçek ihtiyaç canlı görüntü, kayıt erişimi, olay bilgisi veya analitik olabilir. Bunlar farklı yeteneklerdir. Satın alma değerlendirmesinde önce gerekli işlemleri yazın, sonra cihaz ve istemci tarafındaki uygunluğu ayrı kontrol edin.</p><h2>Model ve sürümü birlikte arayın</h2><p>ONVIF'in resmi uygun ürün veritabanı doğrulama için yetkili kaynaktır. Ürün ailesi adına bakmak yerine tam model ve listelenen yazılım sürümünü inceleyin. Sahaya gelecek cihazın sürümü farklıysa satıcıdan açıklama isteyin. “Aynı serinin başka modeli listede” bilgisi sizin modeliniz için yeterli değildir. Kontrol tarihini satın alma dosyasına ekleyin; liste zamanla değişebilir.</p><h2>İşlev tablosu oluşturun</h2><p>Canlı akış, ses, PTZ, olay bildirimi ve kayıt arama gibi gerekli özellikleri satırlara ayırın. Kamera ve VMS için destek bilgisini karşılıklı yazın. Bazı profil özellikleri koşulludur; profil adının görülmesi bütün seçeneklerin üründe uygulanmış olduğunu söylemez. ONVIF profil açıklaması ile üreticinin sürüm notlarını birlikte değerlendirin. Marka adı üzerinden genel uyumluluk kararı vermeyin.</p><h2>Örnek kabul senaryosu</h2><p>Depo için canlı görüntü ve kesinti sonrası kayıt erişimi gerekiyor olsun. Yalnızca canlı akışın açılmasını kabul testi saymayın. Kamerayı yeniden bağladıktan sonra ilgili zaman aralığının bulunmasını, görüntünün oynatılmasını ve olay saatinin doğru görünmesini ayrıca kontrol edin. Bu işlemler test cihazında, seçilen firmware ve VMS sürümüyle yapılmalıdır. Başka ortamdan alınan video kaydı entegrasyonu kanıtlamaz.</p><h2>Sonuçları koşullarıyla kaydedin</h2><p>Başarılı işlevin yanında kullanılan codec, çözünürlük ve yetki rolünü yazın. Yönetici hesabıyla çalışan bir işlem operatör hesabında çalışmayabilir. Başarısızlık halinde üretici uzantısı mı, profil eksikliği mi, erişim politikası mı olduğunu ayırın. Genel “ONVIF çalışmıyor” kaydı destek ekibine yeterli bilgi vermez; yeniden üretilebilir adımlar hazırlayın.</p><p>Son kararın yalnızca protokol listesine dayanmasına izin vermeyin. Bakım desteği, güncelleme süreci ve kayıt yazılımının sürüm takvimi de işletimi etkiler. Uygunluk doğrulaması gerekli bir aşamadır fakat sahadaki uçtan uca denemenin yerine geçmez. Özellikle toplu alım öncesinde temsilci cihazla yapılmış ve sonuçları kaydedilmiş pilot, sonradan ortaya çıkacak özellik sürprizlerini azaltır.</p>`, [['ONVIF uygun ürün veritabanı', 'https://www.onvif.org/conformant-products/'], onvif('t')], 'dns-sd-hizmet-kesfi'),
article('kamera-ana-alt-akis', 'Ana akış ve alt akış için ayrı kabul ölçütleri belirlemek', cameras,
'Kayıt kalitesi ile çoklu kamera izleme yükünü aynı video profiline zorlamadan tasarlayın.',
`<p>Kayıt için seçilen yüksek ayrıntılı video akışı her operatör ekranında aynı anda açıldığında istemci zorlanabilir. Alt akış daha düşük kaynak tüketimiyle genel izleme için kullanılabilir; fakat kritik ayrıntıyı koruduğu ayrıca doğrulanmalıdır. Ana ve alt akışı yalnızca “yüksek” ve “düşük” etiketleriyle değil, hangi işi destekledikleriyle tanımlayın.</p><h2>Kullanım amacını ayırın</h2><p>Kayıt profili olay sonrasında gereken ayrıntıya göre seçilir. Çoklu görünüm profili operatörün genel hareketi fark etmesine hizmet edebilir. Tek kameraya büyütüldüğünde hangi akışa geçileceğini VMS ayarında kontrol edin. Ekranda büyüyen görüntünün otomatik olarak daha yüksek ayrıntılı kaynağa geçtiğini varsaymayın. Dijital büyütme kayıtta bulunmayan ayrıntıyı oluşturmaz.</p><h2>Profil değerlerini birlikte kaydedin</h2><p>Codec, çözünürlük, kare hızı, bitrate kontrolü ve anahtar kare davranışı aynı profili tanımlar. Sadece çözünürlük not etmek yeterli değildir. Bir ayarı değiştirdiğinizde diğer işlevleri etkileyip etkilemediğini üretici dokümanından kontrol edin. Cihazın aynı anda sunabileceği farklı akış sayısı da modele bağlıdır. İstemci talepleri kamera işlem yüküne katkı sağlayabilir.</p><h2>Örnek kontrol masası</h2><p>Operatör on altı kamerayı küçük kutularda izliyor, olay olduğunda birini tam ekrana açıyor olsun. Küçük görünümde genel hareketin seçilebildiğini, tam ekranda gereken ayrıntının geldiğini ve geçişte kabul edilemez bekleme oluşmadığını test edin. On altı burada tasarım örneğidir, donanım kapasitesi iddiası değildir. Aynı testi gerçek istemci bilgisayarı ve hedef ekran düzeniyle yapın.</p><h2>Kayıt yolunu ayrıca doğrulayın</h2><p>Canlı görünümde alt akış kullanılması kayıt sunucusunun da alt akışı kaydettiği anlamına gelmez; tersini de varsaymayın. VMS'nin hangi profili kayıt için istediğini inceleyin. Bir örnek kayıt dışa aktarın ve çözünürlük ile kare hızını kontrol edin. Ekrandaki canlı görüntüye bakıp kayıt kalitesi hakkında karar vermek yanlış kabul sonucuna yol açabilir.</p><p>Son olarak ağ, kamera ve istemci yükünü ayrı izleyin. Sorunun decode kapasitesi olduğu durumda yalnızca anahtar bant genişliğini artırmak fayda sağlamayabilir. Düşük kaynaklı istemcide alt akış politikası uygun olabilir; fakat iş gereksinimini karşılamıyorsa çözüm sadece kaliteyi azaltmak değildir. Kabul dokümanı her görünümde neyin seçilebilir olması gerektiğini açıkça tarif etmelidir.</p>`, [axis('latency-in-live-network-video-surveillance'), onvif('t')], 'mbps-mb-s'),
article('kamera-bitrate-sahne-testleri', 'Kamera bitrate planında gündüz ölçümü neden yetmez?', cameras,
'Hareket, ışık ve sahne değişimlerini kapsayan ölçüm planıyla kayıt ve ağ kapasitesini daha gerçekçi değerlendirin.',
`<p>Boş bir koridorda öğlen ölçülen video trafiği, yağmurlu bir gecedeki dış saha kamerasını temsil etmez. Kodlanan veri sahne ayrıntısına, harekete ve görüntü ayarlarına bağlı olarak değişebilir. Bu nedenle tek anlık değerle ağ ve depolama planı yapmak eksik kalır. Önce hangi koşulların gerçek işletimi temsil ettiğini belirleyin.</p><h2>Temsilci sahneler seçin</h2><p>Giriş çıkış yoğunluğu, gece aydınlatması, hareketli bitki örtüsü ve temizlik saatleri gibi koşulları listeleyin. Her kamerayı günlerce izlemek mümkün değilse benzer sahnelerden temsilciler seçin. Seçimin nedenini belgeleyin. Sabit ofis ile dış otoparkı aynı grup saymak kolaydır fakat sıkıştırma davranışları farklı olabilir. Ölçüm penceresini yalnızca ekibin rahat çalıştığı saatlere göre seçmeyin.</p><h2>Ortalama ile tepeyi ayırın</h2><p>Depolama hesabında zaman içindeki toplam veri, ağ bağlantısında ise eşzamanlı yük önem taşır. Kısa tepe değerlerini uzun dönem ortalaması gibi kullanmak kapasiteyi abartabilir; sadece ortalamaya bakmak da yoğun anlarda darboğazı gizleyebilir. Hangi istatistiği hangi amaç için kullandığınızı rapora yazın. Kamera arayüzündeki hedef bitrate ile ölçülen ağ trafiği aynı değer olmayabilir.</p><h2>Örnek ölçüm günlüğü</h2><p>Bir kapı kamerası için sahne durumu, codec, çözünürlük, kare hızı, bitrate kontrol modu ve gözlem süresini kaydedin. Ayar değiştiğinde yeni satır açın. Böylece gece artışının sahneden mi yoksa değişen profilden mi kaynaklandığı araştırılabilir. İki farklı profildeki sonuçları tek ortalamada birleştirmek sonraki kapasite hesabını anlaşılmaz hale getirir.</p><h2>Sınır koymanın bedelini görün</h2><p>Bitrate sınırı ağ yükünü yönetmeye yardımcı olabilir; fakat sahne karmaşıklaştığında görüntü ayrıntısı veya başka kalite bileşenleri etkilenebilir. Kabul testi yalnızca trafiğin sınır altında kalmasını kontrol etmemelidir. Olay açısından önemli ayrıntının kayıt üzerinde okunabildiğini de inceleyin. Üreticinin bitrate kontrol açıklamalarını kendi sahnenizde doğrulayın; pazarlama oranlarını ölçülmüş tasarruf gibi kullanmayın.</p><p>Planın sonunda “bu koşullarda gözlendi” ifadesini koruyun. Mevsim, aydınlatma veya kamera açısı değiştiğinde yeniden örnekleme gerekebilir. Kapasite payını açık varsayımla belirleyin ve işletim sırasında gerçek kullanımın bu varsayıma uyup uymadığını izleyin. Bu yaklaşım kesin bir kamera başına Mbps kuralı vermekten daha çok çalışma ister, ancak yanlış güven oluşturmadan plan yapılmasını sağlar.</p>`, [axis('bitrate-control-for-ip-video'), axis('axis-zipstream-technology')], 'mbps-mb-s'),
article('kamera-kayit-suresi-hesabi', 'Kayıt süresi hesabında kullanılabilir kapasite nasıl ele alınır?', cameras,
'Bitrate hesabını disk etiketiyle karıştırmadan saklama süresini varsayımları açık bir plan haline getirin.',
`<p>“Sekiz terabayt disk kaç gün kayıt tutar?” sorusunun tek yanıtı yoktur. Kamera sayısı, gerçek ortalama bitrate, kayıt takvimi ve kullanılabilir kapasite birlikte gerekir. Diskin kutusundaki sayı doğrudan video için ayrılmış alan değildir. Hesabı önce açık bir model olarak kurun, ardından sistemin gerçek tüketimiyle doğrulayın.</p><h2>Birimleri aynı hale getirin</h2><p>Bitrate bit/s, depolama genellikle byte cinsinden ifade edilir. Sekiz bit bir byte olduğundan dönüşümde bu farkı koruyun. Ondalık GB ve ikili GiB gösterimlerinin farklı olabileceğini raporda belirtin. Basit sürekli kayıt hesabı, toplam ortalama bit/s değerini saniyeyle çarpıp sekize bölmektir. Dosya sistemi ve ürün davranışı için ayrıca pay değerlendirilir.</p><h2>Açıklayıcı örnek</h2><p>Varsayımsal toplam ortalama video akışı 8 Mbit/s ise bir günün ham video hesabı 86,4 GB eder: 8.000.000 × 86.400 ÷ 8. Bu bir kamera ölçümü değildir, birim dönüşümü örneğidir. Ses, metaveri, indeksler ve başka depolama giderleri dahil edilmemiştir. Gerçek sistemde ölçülen veriyle karşılaştırılmadan bu sayı saklama garantisi olarak kullanılmamalıdır.</p><h2>Kullanılabilir alanı doğrulayın</h2><p>RAID düzeni, yedek diskler, ayrılmış alan ve kayıt yazılımının güvenlik payı net kapasiteyi değiştirir. Disklerin toplam etiket kapasitesini hesap tablosuna yazmak yerine VMS'nin video için kullanabildiği alanı kontrol edin. Bazı sistemler doluluk eşiğinde eski kayıtları siler. En eski erişilebilir kayıt tarihini düzenli izlemek planın gerçek hayatta karşılanıp karşılanmadığını gösterir.</p><h2>Olay kaydında görev döngüsü</h2><p>Yalnızca hareket olduğunda kayıt yapılıyorsa süre varsayımı gerçek olay oranına dayanmalıdır. Sessiz gün üzerinden seçilen düşük oran yoğun günleri temsil etmeyebilir. Ön kayıt ve son kayıt süreleri de veri üretir. Sürekli kayıt ile olay kaydını ayrı senaryolar olarak hesaplayın. Olay algılamasının bütün önemli anları yakaladığını ayrıca sınayın; depolama tasarrufu kayıt boşluğunu gizlememelidir.</p><p>Hedef saklama süresini teknik hesapla birlikte işletim gereksiniminden alın. Bu yazı hukuki süre belirlemez. Günlük kullanım grafiği ve en eski kayıt zamanı için izleme kurun. Kamera profilleri değiştiğinde kapasite modelini güncelleyin. Böylece aylar önce yapılmış hesap, yeni çözünürlük veya ek kameralar sonrasında yanlış güven vermeye devam etmez.</p>`, [axis('bitrate-control-for-ip-video'), onvif('g')], 'mbps-mb-s'),
article('kamera-poe-gece-yuku', 'PoE bütçesinde gece yükü ve başlangıç anı nasıl değerlendirilir?', cameras,
'Kamera başına güç desteğini, toplam anahtar bütçesini ve gerçek çalışma koşullarını ayrı kontrol edin.',
`<p>Kamera gündüz çalışıp gece yeniden başlıyorsa yalnızca görüntü ayarlarına bakmak yetmez. Aydınlatma, ısıtıcı veya başka bileşenler devreye girdiğinde güç gereksinimi değişebilir. PoE tasarımında portun desteklediği güç ile anahtarın toplam bütçesi ayrı sınırlardır. Gündüz görülen düşük tüketim bütün koşullarda yeterlilik kanıtı değildir.</p><h2>Üretici değerlerini doğru okuyun</h2><p>Veri sayfasındaki tipik ve maksimum tüketim aynı amaç için kullanılmaz. Hangi işlevlerin ölçüme dahil olduğunu üreticinin açıklamasından kontrol edin. Uygun PoE standardı, gerekli sınıf ve kullanılan enjektör veya anahtar uyumu doğrulanmalıdır. Kablo kayıpları ve güç kaynağının toplam sınırı da hesaba katılır. Rastgele bir watt sayısını bütün kameralara uygulamayın.</p><h2>Toplam bütçe tablosu hazırlayın</h2><p>Her portun cihazını, gereken güç türünü ve tasarımda ayrılan payı listeleyin. Yedek güç kaynağı arızasında kullanılabilir toplam bütçe değişiyorsa bu senaryoyu ayrıca değerlendirin. Port sayısının yeterli olması güç kapasitesinin yeterli olduğu anlamına gelmez. Ek kamera kurulurken boş fiziksel porta bakmak yerine mevcut güç planını güncelleyin.</p><h2>Örnek kontrollü doğrulama</h2><p>Bir dış saha kamerasında gece modu ve desteklenen ısıtma koşullarını üreticinin güvenli test yöntemine göre değerlendirin. Gerçek çevre koşullarını üretmeden varsayımsal maksimum tüketim ölçtüğünüzü söylemeyin. Anahtarın güç olaylarını, kamera yeniden başlama saatini ve bağlantı durumunu birlikte kaydedin. Aynı saatte tekrarlanan olaylar neden araştırmasını daraltır; tek başına kesin teşhis oluşturmaz.</p><h2>Başlangıç ve geri dönüş</h2><p>Elektrik kesintisinden sonra kameraların eşzamanlı başlaması normal işletimden farklı davranabilir. Bakım penceresinde yeniden devreye alma sırasını ve kayıtların geri dönüşünü kontrol edin. Üretim sisteminde sırf deneme için güç kesmeyin; kapsam ve etkisi önceden planlanmalıdır. Güç sorunu şüphesinde kabloyu, portu ve cihazı tek tek karşılaştırın; aynı anda birçok değişiklik yapmak nedeni gizler.</p><p>Son raporda hangi koşulların test edildiğini ve hangilerinin üretici verisine dayandığını ayırın. “Gündüz 6 W gördük, her zaman yeterli” gibi genellemelerden kaçının. Güç bütçesi yaşayan bir işletim belgesidir: IR aydınlatıcı, yeni aksesuar veya kamera modeli değişikliği sonrası tekrar değerlendirilir. Kamera görüntüsü açıkken bile güç marjının doğrulandığı varsayılmamalıdır.</p>`, [axis('typical-and-maximum-power-consumption-in-axis-cameras'), hardening], 'ping-yaniti-yok'),
article('kamera-zaman-korelasyonu', 'Kamera, NVR ve olay kayıtlarının saatleri nasıl eşleştirilir?', cameras,
'Olay araştırmasını zorlaştıran saat dilimi ve zaman kaymasını sistemin bütün bileşenlerinde kontrol edin.',
`<p>Bir kapı geçişi ile kamera kaydı arasında birkaç dakikalık fark olduğunda yanlış zaman aralığı incelenebilir. Görüntü üzerindeki saat, kayıt sunucusunun zamanı ve dışa aktarılan dosyanın zamanı farklı kaynaklardan gelebilir. Hepsinin aynı görünmesi otomatik değildir. Zaman tasarımını kamera kurulumunun son ayrıntısı olarak bırakmayın.</p><h2>Yetkili zaman kaynağını belirleyin</h2><p>Kamera ve kayıt sunucusunun hangi zaman hizmetini kullandığını listeleyin. NTP zaman eşleştirmesi için yaygın bir protokoldür; erişilebilir kaynak, doğru ağ politikası ve uygun cihaz yapılandırması gerekir. Saat dilimi, yaz saati uygulaması ve UTC gösterimi ayrı ayarlardır. Doğru saate sahip cihazın yanlış saat dilimiyle görüntü üretmesi mümkündür.</p><h2>Üç noktada kontrol</h2><p>Kamera yönetim ekranındaki zamanı, VMS olay zamanını ve oynatılan videodaki gösterimi karşılaştırın. Bir referans olay oluşturup hangi anın nerede kaydedildiğini not edin. Bu olay yetkili ve zararsız bir test olmalıdır. Görüntüye eklenen yazının doğru olması dosyanın bütün zaman alanlarının doğru olduğunu kanıtlamaz; dışa aktarma sonucunu da inceleyin.</p><h2>Örnek kapı geçişi</h2><p>Yetkili bir personel belirlenen saatte test kapısından geçsin. Erişim kontrol kaydı, canlı görüntü ve kayıt oynatma ekranı birlikte kontrol edilsin. Fark bulunursa önce gösterim dönüşümünü araştırın; hemen cihaz saatini elle değiştirmeyin. Elle ileri veya geri alınan saat, kayıt sıralamasını etkileyebilir. Değişiklik yapılacaksa üreticinin prosedürü ve bakım penceresi kullanılmalıdır.</p><h2>Kesinti sonrası davranış</h2><p>Zaman sunucusuna erişim kesildiğinde cihazın nasıl davrandığını model dokümanından öğrenin. Bağlantı geri geldiğinde senkronizasyonun yeniden kurulduğunu izleyin. Yeniden başlatma sonrasında yanlış başlangıç saatiyle kayıt oluşup oluşmadığını kabul testine ekleyin. Her cihazın donanım saati veya aynı doğruluk özelliği bulunacağını varsaymayın; üretici ve sürüm farkları önemlidir.</p><p>Olay raporunda kullanılan saat dilimini açık yazın. Farklı şehirdeki ekip dosyayı açtığında kendi yerel saatini olay saati sanmamalıdır. Kaynak cihaz, dışa aktarma zamanı ve varsa gözlenen saat farkı birlikte saklansın. Bu düzen teknik korelasyonu güçlendirir; tek başına herhangi bir hukuki delil standardının karşılandığını iddia etmez. Zaman doğruluğu düzenli bakım kontrolü olarak sürdürülmelidir.</p>`, [rfc(5905), onvif('g')], 'windows-ag-teshis'),
article('kamera-wdr-hareket-kabulu', 'WDR kabul testinde neden hareketli kişi kullanılır?', cameras,
'Aydınlık kapı ve karanlık iç mekân arasında yalnızca sabit görüntüye bakmadan kullanılabilir ayrıntıyı değerlendirin.',
`<p>Kapı önünde boş sahne çok iyi görünürken içeri giren kişinin yüzü seçilemiyorsa WDR ayarı amacına ulaşmamış olabilir. Geniş dinamik aralık teknikleri parlak ve karanlık bölgelerin birlikte gösterilmesine yardımcı olur, fakat hareketli sahnelerde yan etkiler görülebilir. Kabul testi gerçek kullanım görevini temsil etmelidir; güzel bir ekran görüntüsü yeterli değildir.</p><h2>Görevi açık tarif edin</h2><p>Kapıdan geçen kişinin genel hareketini görmek mi, kimliğini seçmek mi, taşıdığı nesneyi ayırt etmek mi gerekiyor? Bu görevlerin ayrıntı ihtiyacı farklıdır. Kameranın açısı ve mesafesi de sonucu etkiler. WDR değerini tek başına artırmak yanlış yerleşimi düzeltmez. Önce beklenen görüntü alanını ve kritik geçiş çizgisini belirleyin.</p><h2>Sabit ve hareketli sahneyi karşılaştırın</h2><p>Aynı ışık koşulunda önce duran, sonra normal hızla geçen yetkili test kişisini gözleyin. Görüntüde çift kenar, bulanıklık veya ayrıntı kaybı olup olmadığını kayıt üzerinden inceleyin. Canlı pencere ile dışa aktarılan kayıt farklı profiller kullanıyorsa bunu not edin. Karşılaştırma boyunca çözünürlük ve diğer temel ayarları sabit tutun.</p><h2>Örnek giriş alanı</h2><p>Öğlen dışarısı parlak, iç koridor karanlık olsun. Test kişisi kapıdan girip önceden belirlenen noktadan geçer. İstenen ayrıntı o noktada değerlendirilir; kişinin kameraya özellikle dönüp durması gerçek senaryoyu temsil etmeyebilir. Akşam aydınlatması farklı olduğundan ayrı kontrol yapılır. Burada herhangi bir kameranın test sonucu verilmez; sahaya uygulanacak kabul yöntemi önerilir.</p><h2>Ayar değişikliğini izlenebilir tutun</h2><p>Her değişiklikte önceki değerleri ve örnek kayıt zamanını saklayın. WDR, pozlama ve gürültü azaltmayı aynı anda değiştirmek hangi etkenin fayda sağladığını belirsizleştirir. Üretici önerilerini başlangıç olarak kullanın, sonra göreve göre karşılaştırın. Veri sayfasındaki dB değerini bütün sahnelerde üstünlük sıralaması gibi değerlendirmeyin; görüntü işleme ve hareket koşulları da belirleyicidir.</p><p>Son kabul cümlesi “WDR açık” olmamalıdır. “Belirlenen geçiş noktasında, test edilen ışık koşulunda istenen ayrıntı kayıt üzerinde seçilebildi” gibi sınırları belli bir ifade kullanın. Mevsimsel güneş açısı ve çevre aydınlatması değiştiğinde yeniden kontrol gerekebilir. Bir ayarın teknik olarak etkin olması, operasyon amacını karşıladığı anlamına gelmez.</p>`, [axis('wide-dynamic-range'), ['Axis görüntü kalitesi sorun giderme', 'https://help.axis.com/en-us/troubleshooting-image-quality']], 'mbps-mb-s'),
article('kamera-kare-hizi-pozlama', 'Kare hızı ile pozlama süresi neden aynı ayar değildir?', cameras,
'Akıcı görüntü ile hareket ayrıntısını ayırarak kamera profilini gerçek olay gereksinimine göre doğrulayın.',
`<p>Yüksek kare hızı akıcı bir video sağlayabilir, fakat her karenin net olduğunu garanti etmez. Pozlama süresi tek karenin ışığı ne kadar süre topladığını etkiler. Hareketli nesne bu süre içinde yer değiştirirse görüntü bulanıklaşabilir. Bu iki ayarı aynı “video kalitesi” düğmesi gibi düşünmek özellikle gece kabul testlerinde yanlış sonuca götürür.</p><h2>İki farklı soruya cevap</h2><p>Kare hızı zaman içinde kaç örnek bulunduğunu anlatır. Pozlama, her örneğin hareket ve ışık özelliklerini etkiler. Daha kısa pozlama bazı hareket ayrıntılarını korumaya yardımcı olabilirken daha az ışık toplar. Sonuç cihazın sensörü, aydınlatma ve görüntü işleme ayarlarına bağlıdır. Bütün sahneler için tek bir en iyi değer yoktur.</p><h2>Önce olay hızını tanımlayın</h2><p>Yürüyen kişi, hızlı araç ve kasa üzerindeki el hareketi aynı gereksinimi taşımaz. Testte gerçekçi hareket hızı ve görüş açısı kullanın. Kişinin kamera önünde durması, hareketli olayın kayda nasıl geçtiğini göstermez. Sadece canlı akışı izlemek yerine kaydı kare kare incelemek yararlı olabilir. Ancak oynatıcıdaki ölçekleme ve işleme de görünümü etkileyebilir.</p><h2>Örnek karşılaştırma</h2><p>Aynı geçişi iki farklı belgelenmiş profille kaydedin. Birinde akış akıcı fakat tek kare bulanık, diğerinde hareket daha net fakat karanlık ayrıntı zayıf olabilir. Bu varsayımsal örnek ayarlar arasındaki ödünleşimi anlatır; gerçek sonuç ölçülmeden üstünlük kararı verilmez. Görev için hangi kaybın kabul edilebilir olduğunu işletim sorumlusu belirlemelidir.</p><h2>Uçtan uca kare korunumu</h2><p>Kamerada seçilen kare hızı kayıt sunucusuna aynı şekilde ulaşmayabilir. Ağ, sunucu ve istemci kapasitesi bütün zincirin parçasıdır. Üretici belgeleri tam kare hızının sistem boyunca değerlendirilmesi gerektiğini vurgular. Kamera ayar ekranının fotoğrafı yerine kayıt üzerinde doğrulama yapın. Kayıp veya düzensizlik varsa hangi katmanda oluştuğunu ayrı ölçün.</p><p>Son profil belgesinde ışık koşulu, test hareketi ve kayıt ayarları birlikte yer almalıdır. Gürültü azaltma veya sıkıştırma değiştiğinde eski kabul sonucunu aynen taşımayın. İş gereksinimini karşılayan profil, en büyük fps sayısını gösteren profil olmak zorunda değildir. Önemli olan kritik olayın gereken ayrıntıyla ve güvenilir zaman örneklemesiyle saklanmasıdır.</p>`, [axis('controlled-full-frame-rate'), ['Axis görüntü kalitesi sorun giderme', 'https://help.axis.com/en-us/troubleshooting-image-quality']], 'hiz-testi-dogru-olcum'),
article('kamera-coklu-istemci-yuku', 'Bir kamera neden tek izleyicide iyi, çok izleyicide yavaş çalışır?', cameras,
'Akış sayısı, profil çeşitliliği ve istemci çözme yükünü birbirinden ayıran kontrollü test planı.',
`<p>Bakım bilgisayarında akıcı görünen kamera, kontrol odasında birkaç pencere açılınca gecikebilir. Sorun yalnızca ağ hızından kaynaklanmayabilir. Kameranın ürettiği farklı akışlar, kayıt sunucusunun dağıtımı ve istemcinin video çözme kapasitesi birlikte değerlendirilmelidir. Hangi bileşenin zorlandığını bilmeden kaliteyi düşürmek geçici ve eksik bir çözüm olabilir.</p><h2>Bağlantı yolunu çizin</h2><p>İstemci doğrudan kameraya mı bağlanıyor, VMS sunucusundan mı video alıyor? Her izleyici kameradan ayrı akış istiyor mu? Aynı profilin yeniden kullanılıp kullanılmadığını ürün mimarisinden öğrenin. Farklı çözünürlük ve codec talepleri farklı işlem yükleri oluşturabilir. Arayüzde aynı kamera görünse de arka plandaki yol aynı olmayabilir.</p><h2>Bir değişkenli test</h2><p>Önce tek istemci ve tek profille başlayın. Ardından istemci sayısını artırıp kamera, ağ, sunucu ve istemci ölçümlerini kaydedin. Sonra profil çeşitliliğini değiştirin. İki şeyi aynı anda değiştirmek neden ayrımını zorlaştırır. Üretici kapasite sınırlarına uyun; testin üretim kayıtlarını etkilememesi için kapsamı önceden belirleyin.</p><h2>Örnek kontrol</h2><p>Bir masaüstünde dört pencere açıldığında CPU yükseliyor fakat kamera ve ağ göstergeleri değişmiyorsa istemci tarafı araştırılabilir. Başka bir istemcide aynı düzenin çalışması bu ihtimali güçlendirir; kesin nedeni tek gözlemle açıklamayın. Donanımsal video çözme desteği, sürücüler ve seçilen codec farklı olabilir. Tarayıcı ile yerel VMS istemcisini aynı performans ortamı saymayın.</p><h2>Dağıtım ve profil kararı</h2><p>VMS'nin yeniden dağıtım veya uygun multicast özellikleri varsa ürün dokümanına göre değerlendirin. Multicast'i rastgele açmak bütün sistemin ölçekleneceğini garanti etmez; ağ ve istemci desteği gerekir. Çoklu görünümde alt akış kullanımı da seçenek olabilir. Ancak kritik ayrıntının kaybolmadığını ve tekli görünüme geçişin doğru profili açtığını doğrulayın.</p><p>Kabul testini gerçek operatör ekran düzeniyle yapın. Tek kameranın boş masaüstünde çalışması bütün kontrol odasının kapasitesini göstermez. Eşzamanlı kayıt, canlı izleme ve geçmiş oynatma yükleri birlikte denenmelidir. Ölçülen koşulları rapora ekleyin; kamera başına evrensel izleyici sayısı vermeyin. Sorun hangi katmanda görünüyorsa iyileştirme o katmanı hedeflemelidir.</p>`, [axis('latency-in-live-network-video-surveillance'), axis('controlled-full-frame-rate')], 'mbps-mb-s'),
article('kamera-kesinti-yerel-kayit', 'Yerel SD kayıt ağ kesintisinde gerçekten devreye giriyor mu?', cameras,
'Kart takılı olmasını yedeklilik sanmadan kesinti, geri bağlantı ve oynatma zincirini doğrulayın.',
`<p>Kamerada SD kart bulunması ağ kesildiğinde kayıtların mutlaka korunacağı anlamına gelmez. Kayıt kuralı, kart durumu, güç devamlılığı ve VMS entegrasyonu birlikte gerekir. Ağ bağlantısını kaybeden kamera aynı kablodan güç alıyorsa fiziksel kabloyu çıkarmak hem veri hem güç kesebilir. Testin hangi arızayı temsil ettiğini doğru seçin.</p><h2>Kesinti türünü tanımlayın</h2><p>Kamera ile kayıt sunucusu arasındaki erişim kaybı, sunucunun kapanması ve kameranın güç kaybı farklı senaryolardır. Yerel depolama bunların hepsine aynı cevap vermez. Önce hangi durumda kayıt beklediğinizi yazın. Ürünün desteklediği yedek kayıt veya otomatik geri doldurma davranışını üretici dokümanından kontrol edin; bütün VMS sistemleri aynı entegrasyonu sunmaz.</p><h2>Kartın işletim durumu</h2><p>Kapasite, uygun kart türü, sağlık durumu ve kayıt izinlerini kontrol edin. Kullanılan ortamın sürekli yazma iş yüküne uygunluğu önemlidir. Kartın görünmesi başarılı kayıt anlamına gelmez; kısa bir örnek kayıt oluşturup oynatın. Depolama dolduğunda eski kayıtların nasıl yönetildiğini ve hata durumunun nasıl bildirildiğini de doğrulayın. Sessiz arıza yedeklilik beklentisini boşa çıkarır.</p><h2>Örnek kontrollü kesinti</h2><p>Bakım penceresinde, kamera gücünü koruyan uygun yöntemle kayıt sunucusuna erişimi geçici kesin. Test başlangıç ve bitiş zamanını not edin. Erişim geri geldiğinde kesinti aralığını kamera ve VMS üzerinden arayın. Yalnızca canlı görüntünün geri dönmesi yeterli değildir. Beklenen kayıtların bulunması, oynatılması ve zaman çizelgesinin açıklanması gerekir.</p><h2>Geri doldurma ile erişim ayrımı</h2><p>VMS yerel kaydı doğrudan oynatabiliyor olabilir; bu, kaydın merkezi depolamaya kopyalandığı anlamına gelmez. İki davranışı ayrı test edin. Kamera sonradan hizmetten çıkarıldığında kayda erişimin sürüp sürmeyeceğini işletim planında değerlendirin. ONVIF Profile G kayıt ve erişim işlevleri için ilgili çerçeveyi sağlar; belirli ürünün bütün iş akışını desteklediği ayrıca doğrulanır.</p><p>Kabul belgesinde test edilen arıza türünü, kartı, firmware'i ve VMS sürümünü yazın. Gerçek kesinti yaşandığında beklenen davranış bu belgeyle karşılaştırılır. Yerel kayıt düzenli sağlık kontrolü gerektirir; bir kez başarılı olan test sonsuza kadar geçerli değildir. Kart değişimi veya yazılım güncellemesi sonrasında kritik senaryoyu yeniden doğrulayın.</p>`, [onvif('g'), ['Axis edge storage', 'https://www.axis.com/products/edge-storage']], 'ping-yaniti-yok'),
article('kamera-rtsp-kontrol-medya', 'RTSP bağlantısı kuruluyor ama görüntü gelmiyorsa nereden başlanır?', cameras,
'Oturum kontrolü ile medya taşınmasını ayırarak kamera, ağ ve oynatıcı arasındaki sorunu daraltın.',
`<p>Bir istemcinin kameraya bağlandığını söylemesi videonun başarıyla taşındığını göstermez. RTSP oturumun kontrolünde rol oynar; medya aktarımı ayrı ayrıntılar içerir. Kimlik doğrulama tamamlanmış olsa bile codec desteği, taşıma seçimi veya ağ politikası görüntüyü engelleyebilir. “Bağlandı” durumunu son kabul ölçütü olarak kullanmayın.</p><h2>Başarısız aşamayı bulun</h2><p>Önce adresin ve kullanılan akış yolunun üretici dokümanıyla eşleştiğini kontrol edin. Yetkili hesabın akışı izleme hakkı olduğundan emin olun. Ardından istemci günlüğünde oturum kurulumu ile medya alma durumunu ayırın. Parolayı içeren bağlantı adreslerini ortak rapora yapıştırmayın. Gerekli kayıtları paylaşırken kimlik bilgilerini çıkarın ve hassas alanları belirtin.</p><h2>Taşıma seçimini belgeleyin</h2><p>Ürünler farklı medya taşıma biçimleri destekleyebilir. UDP veya TCP üzerinden aktarım seçeneğinin tam adı ve davranışı uygulamaya bağlıdır. Bir seçeneğin çalışıp diğerinin çalışmaması ağ yoluna dair ipucu sağlar; otomatik olarak bütün güvenlik duvarını açma gerekçesi değildir. Gerekli akışları üreticinin port belgesine göre tanımlayın.</p><h2>Örnek karşılaştırma</h2><p>Kamera ile aynı yönetim ağındaki yetkili istemcide görüntü geliyor, uzak istemcide gelmiyorsa iki yolun farklarını kaydedin. Aynı codec, hesap ve profil kullanın. Uzak istemcinin decode desteği de farklı olabileceğinden yalnızca ağ politikasını suçlamayın. Kontrol mesajları ile medya paketlerinin gözlenmesi yetkili incelemeyle hangi aşamanın eksik olduğunu belirlemeye yardımcı olabilir.</p><h2>Protokol sürümünü varsaymayın</h2><p>RFC 7826 RTSP 2.0'ı tanımlar; sahadaki her kamera bu sürümü uygulamaz. Cihazın sürüm ve taşıma desteğini kendi belgesinden doğrulayın. RTP de tek başına teslim veya görüntü kalitesi garantisi değildir. Akışın başlaması, uzun süre kararlı kalması ve kayda doğru yazılması ayrı testlerdir.</p><p>Son raporda “görüntü yok” yerine oturum kurulumu, alınan medya ve decode sonucunu ayrı yazın. Bu ayrım kamera üreticisi, ağ ekibi ve VMS desteğinin aynı olayı farklı katmanlarda araştırmasını kolaylaştırır. Değişiklik sonrasında kısa canlı kontrolle yetinmeyin; ilgili kayıt aralığını da oynatarak işlevin uçtan uca döndüğünü doğrulayın.</p>`, [rfc(7826), rfc(3550)], 'tcp-udp-port-farki'),
article('kamera-metadata-kabul', 'Analitik olay verisi için ayrı kabul testi nasıl yazılır?', cameras,
'Video akışı çalışırken kişi veya araç olaylarının neden ayrıca doğrulanması gerektiğini öğrenin.',
`<p>Bir kamera VMS'ye görüntü gönderirken analitik olayları hiç ulaşmayabilir. Video ve metaveri aynı işlev değildir. Operatörün kişi algılama olayına göre arama yapması gerekiyorsa canlı görüntünün açılması kabul için yetersizdir. Önce hangi olayın hangi ekranda ve hangi alanlarla görünmesi gerektiğini tanımlayın.</p><h2>Olay sözleşmesini yazın</h2><p>Olay türü, zaman, kaynak kamera, varsa sınıflandırma ve ilgili kayıt bağlantısı beklenen alanlar olabilir. Her alanın cihazda ve VMS'de nasıl adlandırıldığını eşleştirin. ONVIF Profile M analitik metaveri ve olaylar açısından ilgili profildir; bütün cihazların bütün analitik sınıfları ürettiğini varsaymayın. Ürün özelliği ile profil çerçevesini ayırın.</p><h2>Doğru ve yanlış durum örnekleri</h2><p>Yetkili test kişisi belirlenmiş bölgeye girdiğinde beklenen olayın oluşmasını kontrol edin. Bölge dışında kalan hareketin aynı olayı üretip üretmediğini de inceleyin. Bu küçük test genel doğruluk oranı iddiası için yeterli değildir; entegrasyonun temel işleyişini gösterir. Hava, ışık ve görüş açısı değiştikçe sahaya özgü daha geniş değerlendirme gerekebilir.</p><h2>Zaman ve kayıt ilişkisi</h2><p>Olay listesinden görüntüye geçildiğinde doğru kamera ve zaman aralığı açılmalıdır. Bir olayın bildirim paneline gelmesi kayda doğru bağlandığını göstermez. Kamera ile sunucu saat farkını kontrol edin. Aynı olayın iki kez görünmesi durumunda yeniden bağlantı veya aktarım tekrarlarını araştırın; otomatik silme kuralıyla olayı gizlemeyin.</p><h2>Örnek bakım sonrası kontrol</h2><p>Firmware güncellemesinden sonra video devam ediyor fakat sınıflandırma alanı boş kalıyorsa profil veya entegrasyon davranışı değişmiş olabilir. Önceki kabul örneğini aynı koşullarda tekrarlayın. Kullanılan sürümleri ve olayın ham alanlarını erişim kontrollü kayıtta saklayın. Arayüz çevirisi ile protokol alanını birbirine karıştırmamak destek sürecini kolaylaştırır.</p><p>Kabul belgesinde hangi olayların test edildiğini açıkça listeleyin. Bir kişi olayının çalışması araç sayımı veya başka analitiklerin de çalıştığını kanıtlamaz. Kullanıcıya doğrulanmamış otomasyon vaat etmeyin. Analitik sonucun insan incelemesini nerede gerektirdiğini iş akışında belirtmek, teknik entegrasyon kadar önemlidir.</p>`, [onvif('m'), onvif('t')], 'dns-sd-hizmet-kesfi'),
article('kamera-sertifika-yenileme', 'Kamera HTTPS sertifikası yenilenirken kayıt nasıl korunur?', cameras,
'Sertifika değişimini cihaz, VMS güven deposu ve bakım doğrulamasıyla birlikte planlayın.',
`<p>Kamera sertifikası süresi dolduğunda yönetim ekranı uyarı verebilir veya VMS bağlantısı etkilenebilir. Sertifika yalnızca tarayıcıdaki kilit simgesi değildir; istemcinin bağlandığı uç noktanın doğrulanmasında rol oynar. Yenileme sürecini son gün yapılan tek bir dosya yükleme işlemi olarak bırakmak gereksiz kesinti riski doğurur.</p><h2>Bağlantı kimliğini belirleyin</h2><p>VMS kameraya DNS adıyla mı IP adresiyle mi bağlanıyor? Sertifika bu kullanım biçimiyle uyumlu olmalıdır. İstemcinin hangi güven kökünü kullandığını ve ara sertifikaları nasıl işlediğini doğrulayın. Cihazın tarih ve saati yanlışsa geçerli sertifika bile hatalı değerlendirilebilir. Önce kimlik ve zaman tasarımını netleştirin.</p><h2>Pilot cihaz seçin</h2><p>Aynı model ve sürüm ailesinden düşük etkili bir kamerada belgelenmiş yenileme yöntemini deneyin. Eski yapılandırmanın geri dönüş koşullarını kaydedin; özel anahtarın dışa aktarılabilir olduğunu varsaymayın. Sertifika yükleme sonrası yalnızca web ekranını değil, VMS canlı akışını ve kayıt durumunu kontrol edin. Bazı bağlantılar önbellek nedeniyle hemen yeniden kurulmayabilir.</p><h2>Örnek geçiş sırası</h2><p>Önce istemcilerin yeni sertifika zincirini güvenilir olarak tanıyacağını doğrulayın. Sonra planlanan bakım penceresinde cihaz sertifikasını yenileyin. Bağlantıyı ürünün önerdiği biçimde yeniden doğrulayın ve ilgili kayıt aralığında boşluk olup olmadığını inceleyin. “Tarayıcı açıldı” sonucu bütün entegrasyonun doğrulandığı anlamına gelmez. Kayıt ve yönetim yolları farklı olabilir.</p><h2>Sürekli işletim</h2><p>Son kullanma tarihi için önceden bildirim kurun ve sertifika sahibini belirleyin. Kamera değiştiğinde eski sertifikanın ve erişim ilişkisinin nasıl kaldırılacağını yazın. Her modelde aynı otomatik yenileme özelliği bulunmaz. Üretici kılavuzu ile kurumun PKI prosedürünü birlikte uygulayın. Sertifika doğrulamasını kapatmak yenileme sürecinin kalıcı çözümü değildir.</p><p>Değişiklik kaydında eski ve yeni sertifikanın hassas olmayan kimlik bilgileri, işlem zamanı ve doğrulanan işlevler yer alsın. Özel anahtar veya parolalar rapora eklenmemelidir. Bir sorun olduğunda bu kayıt hangi güven ilişkisinin değiştiğini gösterir. Başarılı yenileme, uyarının kaybolmasının yanında beklenen güven ve kayıt işlevlerinin korunmasıdır.</p>`, [hardening, ['AXIS Camera Station sistem güvenliği', 'https://help.axis.com/en-us/axis-camera-station-system-hardening-guide']], 'dns-ttl-onbellek'),
article('kamera-guncelleme-pilot-plani', 'Kamera firmware güncellemesi için pilot ve geri dönüş planı', cameras,
'Toplu güncellemeden önce canlı akış, kayıt, olay ve yönetim işlevlerini kapsayan doğrulama hazırlayın.',
`<p>Bir firmware güncellemesinin başarıyla yüklenmesi sistemin bütün işlevlerinin korunduğunu göstermez. Video açılırken olay bildirimleri, saat ayarı veya yerel kayıt davranışı değişebilir. Güncelleme planı dosyanın cihaza aktarılmasından daha geniş olmalıdır. Önce hangi işlevlerin kabul için vazgeçilmez olduğunu ve başarısızlıkta ne yapılacağını belirleyin.</p><h2>Sürüm notlarını iş akışıyla eşleştirin</h2><p>Üreticinin desteklediği yükseltme yolunu, bilinen kısıtları ve entegrasyon notlarını inceleyin. Çok eski sürümden doğrudan geçiş her modelde desteklenmeyebilir. Yapılandırma yedeğinin yeni veya eski sürümde nasıl kullanılabildiğini doğrulayın. Geri dönüşün teknik olarak mümkün olduğunu varsaymayın; bazı geçişlerin özel koşulları vardır. Bu bilgi bakım kararından önce bilinmelidir.</p><h2>Temsilci pilot grubu</h2><p>Her farklı kamera modeli, önemli donanım varyantı ve kritik entegrasyon için temsilci seçin. Yalnızca en yeni kamerayı test etmek eski modellerin davranışını göstermez. Pilot cihazın konumunu ve operasyon etkisini planlayın. Güncelleme öncesinde kısa referans kayıt, olay örneği ve yapılandırma özeti alın; karşılaştırma için başlangıç durumu gerekir.</p><h2>Örnek kontrol sırası</h2><p>Güncelleme sonrası cihaz kimliğini ve sürümünü doğrulayın. Ardından canlı akış, merkezi kayıt, geçmiş oynatma, yetkili operatör erişimi ve kullanılan analitik olayları test edin. Yerel depolama varsa onu da ayrı inceleyin. Testler tamamlanmadan diğer cihazlara yaymayın. Aynı gün içinde hepsini bitirme hedefi, işlev kaybını kabul etme gerekçesi değildir.</p><h2>Geri dönüş kararını önceden yazın</h2><p>Hangi hata yayılımı durduracak? Kim karar verecek? Geçici izleme veya alternatif kayıt nasıl sağlanacak? Bu sorular sorun çıktığında ilk kez cevaplanmamalıdır. Üreticinin desteklediği geri dönüş yolu yoksa cihaz değiştirme veya kontrollü düzeltme planı gerekebilir. Önceki sürüm dosyasını saklamak tek başına uygulanabilir geri dönüş planı değildir.</p><p>Toplu dağıtımı küçük gruplar halinde yapıp her grubun sonucunu kaydedin. Güncelleme kabulü yalnızca versiyon sayısının değişmesine değil, belirlenen işlevlerin tekrar çalışmasına dayanmalıdır. Sonraki bakım ekibi hangi testlerin yapıldığını görebilmelidir. Bu yöntem yama uygulamasını gereksiz yere ertelemek için değil, güvenlik ve işletim sürekliliğini birlikte yönetmek içindir.</p>`, [['AXIS Device Manager güvenlik kılavuzu', 'https://help.axis.com/en-us/adm-security-guide'], ['AXIS Camera Station sistem güvenliği', 'https://help.axis.com/en-us/axis-camera-station-system-hardening-guide']], 'windows-ag-teshis'),
article('kamera-maske-kayit-kontrolu', 'Gizlilik maskesi canlı görüntüde ve kayıtta nasıl doğrulanır?', cameras,
'Maskenin hangi akışlara uygulandığını kontrol ederek yalnızca ekran üzerinde gizlenen görüntüyü kalıcı maskeleme sanmayın.',
`<p>Operatör ekranında bir alanın kapalı görünmesi, aynı alanın bütün kayıtlarda ve dışa aktarmalarda da kapalı olduğu anlamına gelmez. Maske kamerada, VMS'de veya yalnızca görüntüleme katmanında uygulanabilir. Önce kullanılan özelliğin tam olarak nerede çalıştığını belirleyin. Teknik doğrulama, kurumun gizlilik politikasında istenen davranışla eşleşmelidir.</p><h2>Akışları ayrı listeleyin</h2><p>Ana akış, alt akış, görüntü karesi alma, yerel kayıt, merkezi kayıt ve dışa aktarma farklı yollardır. Kullanılan maske özelliğinin bunların hangisini etkilediğini ürün dokümanından kontrol edin. Bir yolda başarılı sonuç diğerlerini kanıtlamaz. Yetki rolüne göre maskesiz erişim varsa bunun kimlere verildiğini ve nasıl kaydedildiğini ayrıca inceleyin.</p><h2>Sabit ve hareketli maske</h2><p>Sabit bölge maskesi belirlenmiş alanı kapatır. Nesneye bağlı dinamik maskeleme farklı bir mekanizmadır ve model desteğine bağlı olabilir. Dinamik özellikte nesnenin kaçırılması veya sınırda gecikme gibi durumlar için kabul senaryosu yazın. Üreticinin genel tanıtımını sıfır hata garantisi olarak sunmayın; gerçek sahne koşullarıyla değerlendirme gerekir.</p><h2>Örnek pencere alanı</h2><p>Kameranın görmesi gerekmeyen bir pencere maskelensin. Canlı görüntü, geçmiş kayıt ve dışa aktarılan kısa klipte aynı alanı kontrol edin. Kamera açısı veya çözünürlük değiştiğinde maskenin doğru yerde kalıp kalmadığını yeniden sınayın. PTZ kamerada farklı konumlar ayrıca değerlendirilmelidir. Bir konumda doğru görünen maske bütün hareket aralığını otomatik kapsamayabilir.</p><h2>Değişiklik yönetimi</h2><p>Maskeyi kimin değiştirebileceğini belirleyin. Bakım için kaldırılan maske tekrar etkinleştirildiğinde kontrol kaydı oluşturun. Sadece ayarın açık olduğunu görmek yeterli değildir; örnek kayıt üzerinden sonuç incelenmelidir. Kamera değişimi veya firmware güncellemesi sonrası maske kabul testini tekrarlayın. Yapılandırma yedeği uygulanınca beklenen bölgelerin korunduğunu varsaymayın.</p><p>Bu rehber teknik doğrulama yöntemidir; hangi alanların kaydedilebileceği veya hangi saklama süresinin yasal olduğu konusunda hüküm vermez. Kurumun yetkili gizlilik sorumlusu gereksinimi belirlemelidir. Teknik ekip de bu gereksinimin bütün görüntü yollarında gerçekten uygulandığını kanıtlamalıdır. Güvenilir maskeleme, güzel görünen tek bir ekran görüntüsünden daha kapsamlı bir kabul süreci ister.</p>`, [axis('privacy-in-surveillance'), ['AXIS Live Privacy Shield kılavuzu', 'https://help.axis.com/en-us/axis-live-privacy-shield']], 'dns-sd-hizmet-kesfi'),
article('kamera-gece-yansima-teshisi', 'Gece görüntüsündeki sis ve parlama ağ sorunu mu?', cameras,
'IR yansıması, kir ve sahne aydınlatmasını paket kaybıyla karıştırmadan görüntü sorununu sınıflandırın.',
`<p>Gece görüntüsünde beyaz perde veya parlak lekeler görülmesi hemen ağ kapasitesi sorununa işaret etmez. Optik yüzey, yakın yansıtıcı nesne ve aydınlatma yerleşimi görüntüyü etkileyebilir. Ağ sorunu araştırmadan önce bozulmanın kameranın ürettiği karede mi yoksa taşıma sırasında mı ortaya çıktığını ayırmak yararlıdır.</p><h2>Belirtiyi somut tarif edin</h2><p>Görüntü donuyor mu, bloklara mı ayrılıyor, bütün sahne düşük kontrastlı mı, yalnızca belirli bölgede parlama mı var? Bu belirtiler aynı nedenle oluşmak zorunda değildir. Sorunun başladığı saati ve gece moduna geçişle ilişkisini not edin. Gündüz ve gece örneklerini aynı açıdan saklayın. Birden fazla ayarı aynı anda değiştirmeden başlangıç durumunu koruyun.</p><h2>Optik ve çevresel kontrol</h2><p>Üreticinin güvenli bakım yönergelerine göre ön yüzeyi ve muhafazayı kontrol edin. Kir, örümcek ağı veya yakın duvar gibi unsurlar gece aydınlatmasını etkileyebilir. Kamerayı açma, temizleme ve yeniden kapatma işlemleri modele bağlıdır; rastgele kimyasal veya yöntem kullanmayın. Montaj koşullarının cihazın çevresel gereksinimlerine uyduğunu değerlendirin.</p><h2>Örnek karşılaştırma</h2><p>Yerel yetkili görüntüleme ile VMS kaydında aynı parlama görülüyorsa görüntü üretimi ve sahne tarafı araştırılabilir. Yalnızca uzak istemcide bozulma varsa ağ ve decode yolu ayrıca kontrol edilir. Bu karşılaştırma kesin teşhis değildir; arızanın katmanını daraltır. Her iki görüntünün aynı profil ve zamana ait olduğundan emin olun.</p><h2>Aydınlatma ve pozlama</h2><p>Gece modu, IR ışığı ve pozlama ayarlarını üretici kılavuzuyla birlikte değerlendirin. Bir ayarın görüntüyü daha parlak yapması gereken ayrıntıyı daha okunur yapmayabilir. Hareketli kişiyle kısa kontrollü örnek alın ve kayıt üzerinden inceleyin. Yansıma sorununu sadece bitrate artırarak çözmeye çalışmak depolama yükünü büyütüp asıl nedeni bırakabilir.</p><p>Bakım sonucunu “görüntü düzeldi” ifadesinden daha açık kaydedin: hangi fiziksel veya ayar değişikliği yapıldı, hangi ışık koşulunda kontrol edildi? Yağmur veya farklı gece aydınlatması henüz test edilmediyse bunu belirtin. Tek bir başarılı kare bütün çevresel koşullar için garanti değildir. Düzenli görsel kontrol, ağ izleme ekranının fark edemeyeceği optik bozulmaları yakalamaya yardımcı olur.</p>`, [['Axis görüntü kalitesi sorun giderme', 'https://help.axis.com/en-us/troubleshooting-image-quality'], axis('wide-dynamic-range')], 'ping-yaniti-yok'),
article('kamera-segmentasyon-kabul', 'Kamera VLAN tasarımında izin verilen yollar nasıl test edilir?', cameras,
'Kayıt ve bakım bağlantılarını korurken gereksiz erişimi sınırlayan uçtan uca kabul matrisi hazırlayın.',
`<p>Kameraları ayrı VLAN'a taşımak yararlı bir düzenleme olabilir; fakat VLAN etiketi tek başına erişim politikasını tanımlamaz. Hangi sistemin kameraya hangi amaçla bağlanacağı açık olmalıdır. Kayıt sunucusu, bakım bilgisayarı ve operatör istemcisi farklı gereksinimlere sahip olabilir. Tasarımı bu iş akışlarından başlayarak kurun.</p><h2>İletişim matrisi</h2><p>Kaynak, hedef, protokol, amaç ve sorumlu alanlarından oluşan tablo hazırlayın. Kayıt akışı, yönetim, zaman ve isim çözümleme gibi gereken yolları ayrı yazın. Üreticinin port listesini doğrudan bütün ağa izin kuralına dönüştürmeyin. Yalnızca kullanılan özellikler için gerekli bağlantıları değerlendirin. Bazı entegrasyonlar ek bağlantı gerektirebilir; bunlar açık gerekçeyle belgelenmelidir.</p><h2>Olumlu ve olumsuz testler</h2><p>Kayıt sunucusunun beklenen akışı almasını test etmek olumlu kontroldür. Yetkisiz kullanıcı ağından yönetim erişiminin engellendiğini doğrulamak olumsuz kontroldür. İkisi birlikte gerekir. Bir portun görünmemesi kameranın kapalı olduğu anlamına gelmez; kaynak bölgeye göre politika sonucu olabilir. Test raporunda kaynağı mutlaka belirtin.</p><h2>Örnek bakım yolu</h2><p>Operatörler görüntüyü VMS üzerinden izliyor, doğrudan kamera yönetimine yalnızca bakım istasyonu erişiyor olsun. Kamera VLAN'ından kullanıcı ağına gereksiz bağlantıların engellenmesi ayrıca değerlendirilir. Her kural değişikliği sonrası canlı video ve geçmiş oynatma kontrol edilir. Kamera saat kaynağına erişim unutulursa görüntü açık kalırken olay zamanları bozulabilir.</p><h2>Keşif davranışı</h2><p>Yerel keşif mekanizmaları farklı VLAN'larda otomatik çalışmayabilir. Bu beklenen bir sınır olabilir; bütün yayın trafiğini taşımak zorunda değilsiniz. VMS'ye belgelenmiş adresle cihaz ekleme veya yetkili yönetim aracı seçeneklerini değerlendirin. Keşif kolaylığı için ağ ayrımının amacını ortadan kaldırmayın. Kullanılan çözümün bakım sırasında nasıl işletileceğini yazın.</p><p>Geçiş öncesinde mevcut kural ve yapılandırmaların geri dönüş planını hazırlayın. Önce küçük bir kamera grubuyla deneyin. Güvenlik kuralının doğru uygulanması kadar kaydın kesintisiz sürdüğünün doğrulanması da önemlidir. Sonuç, “ayrı VLAN kuruldu” değil, gerekli yolların çalıştığı ve gereksiz yolların beklenen şekilde sınırlandığı bir kabul matrisi olmalıdır.</p>`, [['AXIS Camera Station sistem güvenliği', 'https://help.axis.com/en-us/axis-camera-station-system-hardening-guide'], hardening], 'varsayilan-ag-gecidi'),
article('kamera-disari-aktarma-dogrulama', 'Video dışa aktarımı neden ayrı bir kabul testidir?', cameras,
'Kayıt VMS içinde oynarken dışa aktarılan dosyanın açılmasını, zamanını ve bütünlük bilgisini ayrıca doğrulayın.',
`<p>Bir olayın VMS ekranında bulunması teslim edilebilir bir video dosyasının hazır olduğu anlamına gelmez. Dışa aktarma farklı codec, kapsayıcı veya özel oynatıcı gerektirebilir. Dosya başka bilgisayarda açılmıyorsa kayıt mevcut olsa bile operasyon ihtiyacı karşılanmamıştır. Bu nedenle dışa aktarmayı kurulum kabulünün ve periyodik bakımın parçası yapın.</p><h2>Alıcının ihtiyacını belirleyin</h2><p>Dosya kurum içi inceleme, teknik destek veya yetkili dış paylaşım için hazırlanabilir. Gerekli görüntü aralığı, kamera bilgisi ve oynatma yöntemi bu amaca göre belirlenir. Bütün arşivi dışa aktarmak yerine gerekli aralık seçilsin. Paylaşım yetkisi ve saklama prosedürü kurumun politikasıyla uyumlu olmalıdır; teknik olarak aktarılabilir olması paylaşım izni anlamına gelmez.</p><h2>Bağımsız oynatma kontrolü</h2><p>Kısa bir test aralığını dışa aktarın ve mümkünse farklı yetkili bilgisayarda açın. Görüntü, ses gerekiyorsa ses, zaman gösterimi ve kamera kimliği kontrol edilsin. VMS oturumu açıkken çalışan bağlantı dışarıda bağımsız dosya olmayabilir. Gerekli oynatıcı varsa güvenilir kaynağını ve sürümünü belgeleyin. Kullanıcıyı belirsiz codec indirmelerine yönlendirmeyin.</p><h2>Bütünlük ile doğruluk ayrımı</h2><p>Dosya özeti, aktarım sırasında dosyanın değişip değişmediğini kontrol etmek için kullanılabilir; görüntünün çekildiği sahnenin doğru yorumlandığını kanıtlamaz. Ürünün imzalı video özelliği varsa doğrulama aracı ve desteklenen iş akışını ayrıca test edin. İmza desteğini bütün kameralarda varsaymayın. Yeniden kodlama veya düzenleme işleminin doğrulama bilgisini etkileyip etkilemediğini ürün belgesinden inceleyin.</p><h2>Örnek teslim paketi</h2><p>Video dosyası, ilgili kamera adı, zaman aralığı ve saat dilimi kısa bir notla birlikte verilsin. Teknik bütünlük kontrolü yapıldıysa kullanılan yöntem ve sonuç kaydedilsin. Düzenlenmiş bir kopya hazırlanmışsa bunu özgün dışa aktarımla karıştırmayın. Dosyaların adlandırılması ve erişim izinleri teslim sırasında kontrol edilsin.</p><p>Bu süreç tek başına herhangi bir mahkemenin delil koşullarını karşılama iddiası taşımaz. Ama teknik teslimin tekrar üretilebilir olmasını sağlar. Kabul sonunda yalnızca “export düğmesi çalışıyor” yazmayın; seçilen aralığın beklenen içerikle bağımsız açıldığını belirtin. Yazılım güncellemeleri ve dışa aktarma ayarı değişikliklerinden sonra örnek testi tekrarlayın.</p>`, [axis('axis-edge-vault'), ['Axis imzalı video açıklaması', 'https://newsroom.axis.com/article/trust-signed-video']], 'windows-ag-teshis'),
article('kamera-hizmetten-cikarma', 'IP kamera hizmetten çıkarılırken hangi kayıtlar güncellenmeli?', cameras,
'Fiziksel sökümün yanında hesap, sertifika, depolama ve envanter ilişkilerini kontrollü olarak kapatın.',
`<p>Kamerayı duvardan sökmek hizmetten çıkarma işleminin yalnızca fiziksel kısmıdır. VMS hesabı, ağ izinleri, sertifikalar ve yerel depolama geride kalabilir. Yeni cihaz aynı IP adresini aldığında eski kayıtlar yanlış kamerayla eşleşebilir. Kapatma süreci cihaz yaşam döngüsünün planlı ve izlenebilir bir aşaması olmalıdır.</p><h2>Önce kayıt gereksinimini netleştirin</h2><p>Cihazdaki yerel kayıtların korunması gerekiyor mu, merkezi arşiv nasıl ilişkilendirilecek? Bu kararlar yetkili işletim ve gizlilik sorumlularıyla verilmelidir. Silme veya sıfırlama işlemine başlamadan gerekli kayıtların erişilebilir olduğundan emin olun. Bir dosyanın kopyalanması başarılı yedek anlamına gelmez; örnek oynatma ve beklenen zaman aralığı kontrol edilmelidir.</p><h2>Kimlik ilişkilerini kapatın</h2><p>VMS cihaz kaydı, izleme sistemi, DHCP rezervasyonu ve envanter bağlantılarını gözden geçirin. Geçmiş kayıtların anlamını koruyarak aktif cihaz listesinden çıkarın. Eski seri numarasını yeni kameraya taşımayın. IP yeniden kullanılacaksa tarih aralığını açıkça saklayın. Böylece geçmiş olayın hangi fiziksel cihazdan geldiği sonradan anlaşılır.</p><h2>Erişim ve sırlar</h2><p>Cihaza özel hesaplar ve sertifikalar için kurumun iptal prosedürünü uygulayın. Ortak bir yönetim parolası kullanılmışsa bunun başka cihazlarda da etkisi olabilir; değişiklik kapsamını değerlendirin. Fiziksel cihazı başka kuruma devretmeden önce üreticinin güvenli sıfırlama ve depolama yönergelerini izleyin. Fabrika ayarına dönüşün bütün veri ortamlarını sildiğini varsaymayın.</p><h2>Örnek değişim kaydı</h2><p>“Giriş-03” kamerası değiştirildiğinde eski ve yeni seri numarası, söküm zamanı, yeni devreye alma zamanı ve kayıt sürekliliği not edilsin. Eski depolama ortamının nerede tutulduğu veya hangi onaylı işlemle temizlendiği kayıt altına alınsın. Ağ kuralının yeni cihaz için hâlâ gerekli olup olmadığı kontrol edilsin. Aynı konuma kurulmak aynı kimlikte olmak değildir.</p><p>İşlem sonunda eski cihazın aktif yönetim yollarında görünmediğini, yeni cihazın doğru kayıtla eşleştiğini doğrulayın. Arşiv erişimi için gereken eski mantıksal kaydı yanlışlıkla silmeyin. Bu rehber veri imhası için hukuki standart belirlemez; kurumunuzun yetkili prosedürünü teknik kontrol noktalarıyla destekler. Tamamlanmış hizmetten çıkarma, fiziksel, dijital ve belgesel ilişkilerin birlikte kapatılmasıdır.</p>`, [hardening, ['AXIS Device Manager güvenlik kılavuzu', 'https://help.axis.com/en-us/adm-security-guide']], 'dhcp-kira-suresi'),
article('kamera-uc-tan-uca-kabul', 'IP kamera tesliminde uçtan uca kabul senaryosu hazırlamak', cameras,
'Görüntünün açılmasından kayıt arama ve dışa aktarmaya kadar işletimin tamamını doğrulayan saha kontrolü.',
`<p>Kamera kurulumunun bittiği çoğu zaman canlı görüntünün açılmasıyla ilan edilir. Oysa işletim ekibi olay bulmak, geçmişi oynatmak ve gerektiğinde dışa aktarmak zorundadır. Bu zincirin bir halkası eksikse sistem amacını karşılamaz. Kabul planını cihaz özellikleri listesinden değil, kullanıcının gerçek görevlerinden oluşturun.</p><h2>Bir olayın yolculuğunu izleyin</h2><p>Yetkili test kişisi belirlenmiş görüş alanından geçsin. Operatör canlı görüntüde olayı fark etsin, kayıt üzerinde doğru zamanı bulsun ve ilgili aralığı dışa aktarsın. Her aşamada beklenen ayrıntı, zaman ve yetki kontrol edilsin. Test kişisinin gerçek kullanımda olmayacak şekilde durup poz vermesi kabulü kolaylaştırır fakat görevi temsil etmeyebilir.</p><h2>Koşulları çeşitlendirin</h2><p>Gündüz, gece, yoğun görüntü düzeni ve kullanılan olay bildirimi gibi önemli koşulları kapsayın. Bütün olasılıkları tek günde test etmek mümkün olmayabilir. Test edilmeyen koşulları açıkça listeleyip tamamlanma planı oluşturun. “Genel olarak çalışıyor” ifadesi ölçülebilir kabul değildir. Her senaryo için kim, neyi, hangi sonuçla doğruladı bilgisi kaydedilmelidir.</p><h2>Arıza ve geri dönüş</h2><p>Planlı ve güvenli bakım ortamında desteklenen kesinti senaryosunu değerlendirin. Bağlantı geri geldiğinde canlı akışın, kaydın ve gerekiyorsa yerel kayıt erişiminin toparlandığını kontrol edin. Üretim sistemini hazırlıksız kesmeyin. Hangi arızanın simüle edildiği açık olsun; ağ kesintisi testi güç kesintisini veya disk arızasını kanıtlamaz.</p><h2>Yetki ve kullanıcı deneyimi</h2><p>Operatör hesabıyla gerçek görevleri yapın. Yönetici hesabında her şeyin çalışması günlük kullanımı doğrulamaz. Gereksiz yönetim erişiminin kapalı olduğunu, gerekli oynatma ve dışa aktarma izinlerinin doğru verildiğini kontrol edin. Kullanıcı arayüzündeki kamera adı fiziksel konumla eşleşsin. Yanlış etiketlenmiş iki kamera olay araştırmasında ciddi zaman kaybettirebilir.</p><p>Son teslim paketi yapılandırma özeti, test sonuçları, açık eksikler, bakım sorumlusu ve geri dönüş bilgilerini içersin. Başarısız veya yapılmamış testleri başarılı olarak işaretlemeyin. Üretici dokümanları özelliklerin çerçevesini sağlar; sahadaki kabul sonuçları ayrı kanıttır. Sistem ancak belirlenen görevler gerçek kayıt ve kullanıcı rolleriyle doğrulandığında teslim için somut biçimde değerlendirilebilir.</p>`, [axis('quality-with-a-purpose'), onvif('t')], 'hiz-testi-dogru-olcum'),
];
